import React from "react"
import { type SkeletonProps } from "@/components/frames/_slot"
import { EnumChip, type EnumChipEntry } from "@/components/composites/chips/EnumChip"
import { LinkBack } from "@/components/atoms/navigation/Link"
import { Typography } from "@/components/atoms/text/Typography"
import { PageHeader } from "@/components/composites/layout/Page"
import { StackH } from "@/components/frames/Stack"

/**
 * `ChallengeHeader` — the challenge-identity cluster atop the solve page: back
 * link, title, optional description, and a meta row carrying score, difficulty,
 * and the learner's pass-fail status. A `PageHeader` cluster. Two chips on
 * purpose — `difficulty` (a property of the challenge) and `status` (a property
 * of the attempt) are separate axes. Whether the status chip draws, and loading,
 * are data.
 */

/** How hard the challenge is — a property of the CHALLENGE, always known. */
export type ChallengeDifficulty = "easy" | "medium" | "hard"

/** Where the learner's own attempt stands — a property of the ATTEMPT, may not exist yet. */
export type ChallengeStatus = "completed" | "failed" | "inProgress"

/** Difficulty → chip presentation. The block owns this table (§14d.1: no caller-supplied color). */
const DIFFICULTY_MAP: Record<ChallengeDifficulty, EnumChipEntry> = {
    easy: { color: "success", label: "Easy" },
    medium: { color: "warning", label: "Medium" },
    hard: { color: "danger", label: "Hard" },
}

/**
 * Attempt status → chip presentation.
 *
 * `failed` gets a leading icon — a failed/not-passed verdict is a "universal"
 * symbol (cross), not decoration. `completed`/`inProgress` stay text-only; extend
 * the day a screen actually asks for their icon too, not preemptively.
 */
const STATUS_MAP: Record<ChallengeStatus, EnumChipEntry> = {
    completed: { color: "success", label: "Passed" },
    failed: { color: "danger", label: "Failed", icon: "cross" },
    inProgress: { color: "warning", label: "In progress" },
}

/** Props for {@link ChallengeHeader}. */
export interface ChallengeHeaderProps {
    /** Fired when the back link is pressed — the block never owns routing, only the affordance. */
    onBackPress: () => void
    /** Full back-link label override; omit to fall back to `LinkBack`'s generic "Back". */
    backLabel?: string
    /** Challenge title. */
    title: string
    /** One-sentence summary of the challenge. */
    description?: string
    /**
     * Points this challenge is worth, in RAW NUMBER — the block adds the unit
     * itself ("{n} points", §14d.1). Omit when no score is defined yet.
     */
    scoreValue?: number
    /**
     * How hard the challenge is. Always required — every challenge has a fixed
     * difficulty tier independent of whether the learner has attempted it yet.
     */
    difficulty: ChallengeDifficulty
    /**
     * The learner's own attempt outcome. Omit when the learner has not
     * attempted this challenge — the status chip is not drawn at all rather
     * than showing a "not started" chip nobody asked for.
     */
    status?: ChallengeStatus
    /**
     * `true` → every composed atom switches to its own shimmer. The flag FLOWS
     * DOWN into the real atoms rather than building a parallel skeleton tree
     * (§12c).
     */
    isSkeleton?: boolean
}

/**
 * The challenge identity cluster at the top of the solve page. See the file
 * header for why it is a sibling of `ContentHeader` rather than an edit of it.
 *
 * @param props - {@link ChallengeHeaderProps}
 */
const ChallengeHeader = ({
    onBackPress,
    backLabel,
    title,
    description,
    scoreValue,
    difficulty,
    status,
    isSkeleton = false,
}: ChallengeHeaderProps) => {
    // ONE row, all with the same `gap={3}`, sitting close together on the left:
    // CHIPS FIRST (status, difficulty) then the score as plain text. No
    // `prefixIcon={TrophyIcon}`, and status comes before difficulty.
    const metaRow = (
        <>
            {isSkeleton ? (
                <EnumChip
                    value="inProgress"
                    map={STATUS_MAP}
                    isSkeleton

                />
            ) : status != null ? (
                <EnumChip
                    value={status}
                    map={STATUS_MAP}

                />
            ) : null}
            {isSkeleton ? (
                <EnumChip
                    value="easy"
                    map={DIFFICULTY_MAP}
                    isSkeleton

                />
            ) : (
                <EnumChip
                    value={difficulty}
                    map={DIFFICULTY_MAP}

                />
            )}
            {isSkeleton ? (
                <Typography size="xs" color="muted" isSkeleton />
            ) : scoreValue != null ? (
                <Typography
                    size="xs"
                    color="muted"
                    text={`${scoreValue} points`}

                />
            ) : null}
        </>
    )

    return (
        <div>
            <PageHeader

                isSkeleton={isSkeleton}
                breadcrumb={() => (
                    <LinkBack
                        label={backLabel}
                        onPress={onBackPress}
                        isSkeleton={isSkeleton}
                    />
                )}
                title={title}
                // `PageHeader.description` is now a plain `string` (COMPOSITE-4), so this
                // block no longer wraps it in `RichText` at the call site — the field is
                // already typed/documented as a plain one-sentence summary, never markdown,
                // and `PageHeader` now owns the muted styling + skeleton swap itself.
                description={description}
                meta={({ isSkeleton }: SkeletonProps) =>
                    <StackH gap={3} align="center" principle="chip-row"
                        explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                        isSkeleton={isSkeleton} items={[() => metaRow]}  />
                }
            />
        </div>
    )
}

export { ChallengeHeader }

"use client"

import React from "react"
import { ReactFlowProvider } from "@xyflow/react"
import { useTranslations } from "next-intl"
import { Canvas } from "../Canvas"
import { useAppSelector } from "@/redux/hooks"
import { EmptyState } from "@/components/composites/feedback/EmptyState"

/** Props for {@link MindMapCanvas}. */
export type MindMapCanvasProps = Record<string, never>
/**
 * Shared React Flow mind-map canvas: provider wrapper and empty-state handling.
 *
 * Used by both {@link MindMap} (learn shell) and {@link StandaloneMindMap} (public route).
 * The authenticated canvas overlays the viewer's progress (per-module status, the "you
 * are here" module, overall completion) and a content-first "Continue" action; the public
 * standalone route degrades to a structure-only map. Clicking a lesson navigates straight
 * into its reader.
 * @param props - optional className (unused; layout is controlled by the parent container)
 */
export const MindMapCanvas = () => {
    const t = useTranslations()
    const course = useAppSelector((state) => state.course.entity)
    const hasModules = Boolean(course?.modules && course.modules.length > 0)

    if (!course) {
        return null
    }

    if (!hasModules) {
        return (
            <div className={"flex h-full w-full items-center justify-center rounded-2xl border border-dashed dark:border-zinc-600"}>
                <EmptyState title={t("content.mindMapEmpty")} />
            </div>
        )
    }

    return (
        <ReactFlowProvider>
            <div className={"h-full w-full"}>
                <Canvas />
            </div>
        </ReactFlowProvider>
    )
}

"use client"

import React from "react"
import { Handle, type Node, type NodeProps, Position } from "@xyflow/react"
import { cn } from "@heroui/react"

/** React Flow node type id for the course root (two side source handles). */
export const COURSE_ROOT_NODE_TYPE = "courseRoot" as const

/** Handle id: edges to left-column modules attach here. */
export const ROOT_HANDLE_LEFT = "root-left" as const

/** Handle id: edges to right-column modules attach here. */
export const ROOT_HANDLE_RIGHT = "root-right" as const

/** React Flow node data for the `courseRoot` node. */
export type CourseRootNodeData = {
    /** Course title shown in the card. */
    label: string
    /** When true, use compact typography (e.g. no modules placeholder). */
    minimal?: boolean
    /** Overall course completion percent (0-100); omitted for guests / standalone. */
    completionPercent?: number
}

/** React Flow node type for the `courseRoot` node. */
export type CourseRootFlowNode = Node<CourseRootNodeData, typeof COURSE_ROOT_NODE_TYPE>

/** Diameter / stroke of the completion ring (px). */
const RING_SIZE = 72
const RING_STROKE = 6
const RING_RADIUS = (RING_SIZE - RING_STROKE) / 2
const RING_CIRCUMFERENCE = 2 * Math.PI * RING_RADIUS

/**
 * Single overall-completion ring drawn inside the course root: an accent arc over a
 * track, the rounded percent in the centre. This is the ONE total progress meter on
 * the map (per-module nodes show a count, not a bar).
 * @param percent — Completion percent, 0-100.
 */
const CompletionRing = ({ percent }: { percent: number }) => {
    const clamped = Math.max(0, Math.min(100, percent))
    const offset = RING_CIRCUMFERENCE * (1 - clamped / 100)
    return (
        <div className="relative" style={{ width: RING_SIZE, height: RING_SIZE }}>
            <svg width={RING_SIZE} height={RING_SIZE} className="-rotate-90" aria-hidden focusable="false">
                <circle
                    cx={RING_SIZE / 2}
                    cy={RING_SIZE / 2}
                    r={RING_RADIUS}
                    fill="none"
                    stroke="var(--separator)"
                    strokeWidth={RING_STROKE}
                />
                <circle
                    cx={RING_SIZE / 2}
                    cy={RING_SIZE / 2}
                    r={RING_RADIUS}
                    fill="none"
                    stroke="var(--accent)"
                    strokeWidth={RING_STROKE}
                    strokeLinecap="round"
                    strokeDasharray={RING_CIRCUMFERENCE}
                    strokeDashoffset={offset}
                />
            </svg>
            <div className="absolute inset-0 flex items-center justify-center text-base font-semibold text-foreground">
                {`${Math.round(clamped)}%`}
            </div>
        </div>
    )
}

/**
 * Custom root node with left/right source handles so edges can split like a mind map.
 * Shows the overall completion ring when the viewer's progress is known.
 * @param props — React Flow `NodeProps` for `courseRoot` nodes.
 */
export const CourseRootNode = (props: NodeProps<CourseRootFlowNode>) => {
    const { data, selected } = props
    const minimal = Boolean(data.minimal)
    const hasProgress = typeof data.completionPercent === "number"

    return (
        <div
            className={cn(
                "relative flex min-h-[100px] min-w-[300px] w-[300px] flex-col items-center justify-center gap-3 rounded-3xl px-4 py-3 text-center",
                "card card--default",
                "dark:!border-zinc-600/90 dark:!bg-zinc-900/95 dark:!shadow-lg dark:!shadow-black/40",
                minimal
                    ? "text-2xl font-semibold !border-none !shadow-none dark:!border dark:!border-zinc-600 dark:!bg-zinc-900/90"
                    : "!text-xl",
                selected && "ring-2 ring-accent",
            )}
        >
            <Handle
                id={ROOT_HANDLE_LEFT}
                isConnectable={false}
                className="!h-px !w-px !min-h-0 !min-w-0 !border-0 !bg-transparent !opacity-0"
                position={Position.Left}
                type="source"
            />
            {hasProgress ? <CompletionRing percent={data.completionPercent as number} /> : null}
            <div
                className={cn(
                    "max-w-full truncate font-semibold text-foreground",
                    minimal ? "text-2xl" : "text-xl",
                )}
            >
                {data.label}
            </div>
            <Handle
                id={ROOT_HANDLE_RIGHT}
                isConnectable={false}
                className="!h-px !w-px !min-h-0 !min-w-0 !border-0 !bg-transparent !opacity-0"
                position={Position.Right}
                type="source"
            />
        </div>
    )
}

/** Folder-matching handle for the root node — an alias of {@link CourseRootNode}. */
export const RootNode = CourseRootNode

"use client"

import React, { useCallback, useEffect, useState } from "react"
import { createPortal } from "react-dom"
import { Button } from "@heroui/react"
import { ChatCircleIcon, SparkleIcon } from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import {
    useContentAiChatOverlayState,
    useContentAiSelection,
} from "@/hooks/zustand/overlay/hooks"
import { useSelectionHintStore } from "./hintStore"

/**
 * Marker attribute for any readable text region a selection may be asked about —
 * lesson body, foundation body, task brief, challenge brief. Selection only counts
 * when it lands inside an element carrying `[data-ai-selectable]` (no longer bound
 * to the single `#lesson-article` id, so the feature works on every reading surface).
 */
const SELECTABLE_SELECTOR = "[data-ai-selectable]"
/** Ignore trivially short selections (clicks, single words barely worth asking about). */
const MIN_CHARS = 3
/** Cap the stored passage so a huge selection doesn't bloat the prompt / bubble. */
const MAX_CHARS = 600
/** Cap the surrounding-paragraph context fed to the model. */
const MAX_CONTEXT = 700

/** Block elements that count as the "containing paragraph" of a selection. */
const BLOCK_SELECTOR = "p, li, blockquote, td, th, pre, h1, h2, h3, h4, h5, h6"
/** Heading elements used to resolve the section a selection sits under. */
const HEADING_SELECTOR = "h1, h2, h3, h4, h5, h6, [data-toc-label]"

/** Floating button anchor (viewport coords) + the selected passage + its context. */
interface SelectionAnchor {
    /** Horizontal center of the selection, in viewport px. */
    x: number
    /** Top of the selection, in viewport px (the button sits above it). */
    y: number
    /** The trimmed, capped selected text. */
    text: string
    /** Hidden grounding sent to the model: the passage + its containing paragraph + section. */
    context: string
}

/** Resolve the block element (paragraph/list-item/…) containing a selection node. */
const containingBlock = (node: Node | null): Element | null => {
    const start = node?.nodeType === Node.TEXT_NODE ? node.parentElement : (node as Element | null)
    return start?.closest?.(BLOCK_SELECTOR) ?? null
}

/** Resolve the nearest AI-selectable reading region containing a selection node. */
const containingSelectable = (node: Node | null): Element | null => {
    const start = node?.nodeType === Node.TEXT_NODE ? node.parentElement : (node as Element | null)
    return start?.closest?.(SELECTABLE_SELECTOR) ?? null
}

/** Clean text of a heading element (prefer the anchor-free toc label). */
const headingText = (el: Element): string =>
    (el.getAttribute("data-toc-label") ?? el.textContent ?? "").trim()

/** The nearest section heading appearing BEFORE a block within the reading region. */
const nearestHeading = (block: Element | null, region: Element): string | null => {
    if (!block) {
        return null
    }
    let found: Element | null = null
    for (const heading of Array.from(region.querySelectorAll(HEADING_SELECTOR))) {
        // heading precedes the block → it's a candidate section for the selection
        if (heading.compareDocumentPosition(block) & Node.DOCUMENT_POSITION_FOLLOWING) {
            found = heading
        }
    }
    return found ? headingText(found) : null
}

/** Build the hidden `<context>` grounding string from the selection + surroundings. */
const buildSelectionContext = (text: string, paragraph: string, heading: string | null): string => {
    const parts = [`Selected passage: «${text}»`]
    if (paragraph && paragraph !== text) {
        parts.push(`Within paragraph: «${paragraph}»`)
    }
    if (heading) {
        parts.push(`Under section: «${heading}»`)
    }
    return parts.join(". ")
}

/**
 * "Ask AI about this passage" floating action — the entry point for the
 * selection-anchored content-AI flow. Watches for a text selection INSIDE any
 * readable region marked `[data-ai-selectable]` (lesson body, foundation body,
 * task brief, challenge brief); when one settles it shows a small button
 * above the highlight. Pressing it stashes the passage in the overlay store and
 * opens the ask-AI chat ({@link import("./../ContentAiChat").ContentAiChat} reads
 * the passage to scope the next question). Mounted once by the learn layout,
 * alongside {@link import("./../ContentAiFab").ContentAiFab}.
 */
export const ContentAiSelectionAsk = () => {
    const t = useTranslations()
    const { open } = useContentAiChatOverlayState()
    const { setSelection } = useContentAiSelection()
    const [anchor, setAnchor] = useState<SelectionAnchor | null>(null)
    // portal target only exists on the client
    const [mounted, setMounted] = useState(false)
    useEffect(() => setMounted(true), [])

    // first-discovery flag: the button wears a "New" tag until the learner uses
    // it once (or dismisses the inline tip) — see hintStore / SelectionHintCallout
    const seen = useSelectionHintStore((state) => state.seen)
    const hydrate = useSelectionHintStore((state) => state.hydrate)
    const markSeen = useSelectionHintStore((state) => state.markSeen)
    useEffect(() => hydrate(), [hydrate])

    // recompute the button anchor when a selection settles inside a selectable region
    const onSettle = useCallback(() => {
        const selection = window.getSelection()
        if (!selection || selection.isCollapsed || selection.rangeCount === 0) {
            setAnchor(null)
            return
        }
        const range = selection.getRangeAt(0)
        // the selection must land inside a marked reading region ([data-ai-selectable])
        const region = containingSelectable(range.commonAncestorContainer)
        if (!region) {
            setAnchor(null)
            return
        }
        const text = selection.toString().trim()
        if (text.length < MIN_CHARS) {
            setAnchor(null)
            return
        }
        const rect = range.getBoundingClientRect()
        if (rect.width === 0 && rect.height === 0) {
            setAnchor(null)
            return
        }
        // capture the surrounding paragraph + section so a SHORT selection still
        // gives the model enough to reason about (sent hidden, not shown in the UI)
        const block = containingBlock(range.commonAncestorContainer)
        const paragraph = (block?.textContent ?? "").trim().slice(0, MAX_CONTEXT)
        const heading = nearestHeading(block, region)
        const cappedText = text.slice(0, MAX_CHARS)
        setAnchor({
            x: rect.left + rect.width / 2,
            y: rect.top,
            text: cappedText,
            context: buildSelectionContext(cappedText, paragraph, heading),
        })
    }, [])

    useEffect(() => {
        // show on settle (mouse/touch release); hide when the selection collapses
        // (click elsewhere) or the page scrolls (the anchor would drift)
        const onSelectionChange = () => {
            const selection = window.getSelection()
            if (!selection || selection.isCollapsed) {
                setAnchor(null)
            }
        }
        const onScroll = () => setAnchor(null)
        document.addEventListener("mouseup", onSettle)
        document.addEventListener("touchend", onSettle)
        document.addEventListener("selectionchange", onSelectionChange)
        window.addEventListener("scroll", onScroll, true)
        window.addEventListener("resize", onScroll)
        return () => {
            document.removeEventListener("mouseup", onSettle)
            document.removeEventListener("touchend", onSettle)
            document.removeEventListener("selectionchange", onSelectionChange)
            window.removeEventListener("scroll", onScroll, true)
            window.removeEventListener("resize", onScroll)
        }
    }, [onSettle])

    /**
     * Stash the passage + the learner's choice, then open the chat.
     * `forceNewThread=false` ("Ask in this chat", the default/primary action) —
     * `ContentAiChat` appends the quoted question into whichever conversation is
     * already active (or starts a plain new one if none is). `forceNewThread=true`
     * ("New thread") always forks a fresh born-archived side-conversation, even
     * over an already-active one — the app-wide chat's escape hatch for "this is
     * a quick tangent, don't drop it into my real conversation".
     */
    const onAsk = useCallback((forceNewThread: boolean) => {
        if (!anchor) {
            return
        }
        setSelection(anchor.text, anchor.context, forceNewThread)
        markSeen()
        open()
        window.getSelection()?.removeAllRanges()
        setAnchor(null)
    }, [anchor, setSelection, markSeen, open])

    if (!mounted || !anchor) {
        return null
    }

    return createPortal(
        // non-interactive positioning wrapper; onMouseDown only prevents the browser from collapsing
        // the text selection before the real (keyboard-accessible) Buttons' press fires
        // eslint-disable-next-line jsx-a11y/no-static-element-interactions -- see reason above
        <div
            // keep the selection alive when pressing a button (mousedown would
            // otherwise collapse it before the click fires)
            onMouseDown={(event) => event.preventDefault()}
            className="z-[70] flex flex-col gap-1"
            style={{
                position: "fixed",
                left: anchor.x,
                top: Math.max(8, anchor.y - 8),
                transform: "translate(-50%, -100%)",
            }}
        >
            {/* PRIMARY — appends into whatever conversation is already active (the
                app-wide default); SECONDARY — explicitly forks a fresh, hidden
                side-thread for this quote instead. */}
            <Button size="sm" variant="primary" onPress={() => onAsk(false)} className="shadow-lg">
                <SparkleIcon className="size-4" />
                {t("contentAi.askInThisChat")}
                {!seen ? (
                    <span className="rounded-full bg-surface px-2 py-0 text-[11px] font-medium text-accent-soft-foreground">
                        {t("contentAi.new")}
                    </span>
                ) : null}
            </Button>
            <Button size="sm" variant="secondary" onPress={() => onAsk(true)} className="shadow-lg">
                <ChatCircleIcon className="size-4" />
                {t("contentAi.newThread")}
            </Button>
        </div>,
        document.body,
    )
}

import React from "react"
import { ChatsCircleIcon, WarningCircleIcon } from "@phosphor-icons/react"
import { Button } from "@/components/atoms/buttons/Button"
import { Typography } from "@/components/atoms/text/Typography"
import { EmptyState } from "@/components/composites/feedback/EmptyState"
import { StackV } from "@/components/frames/Stack"
import { ContentCommentComposer, type ContentCommentComposerViewer } from "@/components/blocks/learn/ContentCommentComposer"
import { ContentCommentThread, type ContentCommentNode, type ContentCommentThreadCallbacks } from "@/components/blocks/learn/ContentCommentThread"

/**
 * `ContentDiscussion` — talk about this lesson: a label + archive line, an
 * avatar-led collapsible composer, and the threaded comment list, frameless on
 * the page canvas. The empty state is drawn on purpose — no comments yet is an
 * invitation. The composer never hides, and an error replaces the list only.
 * Comment count, archive line, and `hasMore` are states of `Full`; empty, error,
 * and the loading mirror are each their own leaf.
 */

/** Props for {@link ContentDiscussion}. */
export interface ContentDiscussionProps extends ContentCommentThreadCallbacks {
    /** Section label, localized by the caller — e.g. "Discussion" (the block appends "· {total}"). */
    label: string
    /** Current viewer id — drives owner-only edit/delete down the whole tree; null when signed out. */
    currentUserId: string | null
    /** Current viewer identity for the composer's avatar; null when signed out. */
    currentUser?: ContentCommentComposerViewer | null
    /** Top-level comments, newest first. EMPTY -> the invitation is drawn instead. */
    comments: Array<ContentCommentNode>
    /** Total top-level comment count (drives the label + the archive line). */
    total: number
    /** Replies keyed by parent comment id (lazily populated by the caller). */
    repliesByParent: Record<string, ReadonlyArray<ContentCommentNode>>
    /** Post a new top-level comment. */
    onSubmitComment: (body: string) => void
    /** `true` -> more top-level comment pages remain to load. */
    hasMore?: boolean
    /** `true` -> the next page is currently loading. */
    isLoadingMore?: boolean
    /** Load the next page of top-level comments. */
    onLoadMore?: () => void
    /**
 * Set -> the comment list could not be loaded. The message replaces the
 * LIST only: the composer stays, because a failed read did not remove
 * the ability to write.
 */
    errorMessage?: string
    /** `true` -> two placeholder threads mirror the real row shape while the first page loads. */
    isSkeleton?: boolean
}

/** Two placeholder rows so the mirror has the same shape as a short thread. */
const SKELETON_ROWS: Array<ContentCommentNode> = [
    { id: "s1", author: { id: "s1", username: "" }, createdTimeAgo: "", body: "", replyCount: 0, myReaction: null },
    { id: "s2", author: { id: "s2", username: "" }, createdTimeAgo: "", body: "", replyCount: 0, myReaction: null },
]

/**
 * Lesson discussion. See the file header for the full contract.
 *
 * @param props - {@link ContentDiscussionProps}
 */
const ContentDiscussion = ({
    label,
    currentUserId,
    currentUser,
    comments,
    total,
    repliesByParent,
    onSubmitComment,
    onReply,
    onEdit,
    onDelete,
    onReactComment,
    onLoadReplies,
    hasMore = false,
    isLoadingMore = false,
    onLoadMore,
    errorMessage,
    isSkeleton = false,
}: ContentDiscussionProps) => {
    // real (not fabricated) count of currently-loaded top-level comments that already
    // have at least one reply — under-counts before "load more" is exhausted, same
    // tradeoff real `Discussion` documents for its own archive line
    const answeredCount = comments.filter((comment) => comment.replyCount > 0).length

    // no icon here: a chat-bubble icon needs an ASSOCIATION step to read as
    // "discussion" (not a universal symbol like [ok]/(locked)), and the label text already
    // carries the full fact on its own.
    const labelLines = (
        <>
            {isSkeleton ? (
                <Typography weight="medium" isSkeleton />
            ) : (
                <Typography weight="medium" text={`${label} · ${total}`} />
            )}
            {isSkeleton || total > 0 ? (
                <Typography
                    size="xs"
                    color="muted"
                    isSkeleton={isSkeleton}
                    text={`${answeredCount}/${total} questions answered, accumulated over time`}

                />
            ) : null}
        </>
    )

    const discussionHeader = (
        <>
            <StackV gap={2} isSkeleton={isSkeleton} items={[() => labelLines]} />
            <ContentCommentComposer
                onSubmit={onSubmitComment}
                currentUser={currentUser}
                collapsible
                ariaLabel="Write a comment"


            />
        </>
    )

    const commentList = (
        <>
            {(isSkeleton ? SKELETON_ROWS : comments).map((comment) => (
                <ContentCommentThread
                    key={comment.id}
                    comment={comment}
                    currentUserId={currentUserId}
                    currentUser={currentUser}
                    depth={0}
                    repliesByParent={repliesByParent}
                    onReply={onReply}
                    onEdit={onEdit}
                    onDelete={onDelete}
                    onReactComment={onReactComment}
                    onLoadReplies={onLoadReplies}

                />
            ))}
            {!isSkeleton && hasMore ? (
                <Button
                    variant="ghost"
                    size="sm"
                    classNames={["self-center"]}
                    label={isLoadingMore ? "Loading…" : "Show more comments"}
                    isDisabled={isLoadingMore}
                    onPress={onLoadMore}
                />
            ) : null}
        </>
    )

    const discussionBody = (
        <>
            {/* These 3 seams match the real-src `Discussion/index.tsx:98-114` exactly:
 [label+archive]<->composer = grouped (gap-3) · [icon+label]<->archive-line
 = tight (gap-1) · icon<->label = related (gap-2). */}
            <StackV gap={4} isSkeleton={isSkeleton} items={[() => discussionHeader]} />

            {errorMessage != null ? (
                <EmptyState
                    icon={WarningCircleIcon}
                    title={errorMessage}

                />
            ) : !isSkeleton && comments.length === 0 ? (
                // Nobody has written yet. This is an INVITATION, so it is drawn —
                // hiding the section would hide the invitation with it.
                <EmptyState
                    icon={ChatsCircleIcon}
                    title="No discussion yet"
                    description="Ask the first question about this lesson"

                />
            ) : (
                <StackV gap={4} isSkeleton={isSkeleton} items={[() => commentList]} />
            )}
        </>
    )

    return (
        <div>
            <StackV gap={4} isSkeleton={isSkeleton} items={[() => discussionBody]} />
        </div>
    )
}

