export interface OnThisPageProps {
    /**
     * Render as a full-width mobile panel (the bottom-tab "On this page" view):
     * drops the hidden/sticky/width rail chrome and keeps just the body. Default
     * `false` = the desktop right rail.
     */
    mobile?: boolean
}

/**
 * "On this page" rail — the docs-style right outline of the lesson currently
 * being read: the in-article headings with anchor-jump + scroll-spy.
 *
 * Container: reads the active lesson id from Redux (re-scan key) and derives its
 * outline from the rendered article via {@link useTableOfContents}. Self-sizing —
 * renders nothing when the active body has no headings (module overview, code /
 * sandbox tabs, short lessons), so the content reclaims the full width.
 *
 * @param props - {@link OnThisPageProps}
 */
export const OnThisPage = ({ mobile = false }: OnThisPageProps) => {
    const t = useTranslations()
    const contentId = useAppSelector((state) => state.content.id)
    const contentTab = useAppSelector((state) => state.tabs.contentTab)
    const { headings, activeId, onJump } = useTableOfContents(contentId)

    // The rail is the per-lesson sidebar (outline + actions + review + practice), so it shows
    // whenever a lesson is open — NOT only when the body has headings. Earlier it self-hid on
    // `headings.length === 0`, which wrongly dropped the WHOLE rail (incl. actions/review/practice)
    // on the Challenges tab (a card list with no headings) → the layout jumped. Now we hide only
    // when no lesson is open (e.g. module overview) so there is nothing to host.
    if (!contentId) {
        return null
    }

    // shared body: the outline + the per-lesson action/review/practice blocks
    const body = (
        <>
            {/* in-article outline — only when the active body has headings (the prose Content
                tab). The Challenges tab body is a card list with none, so the outline is omitted
                while the rest of the rail stays put. */}
            {headings.length > 0 && (
                <nav className="flex flex-col gap-3">
                    <Label>{t("onThisPage.title")}</Label>
                    <div className="flex flex-col gap-2">
                        {headings.map((heading) => (
                            <Link
                                key={heading.id}
                                onPress={() => onJump(heading.id)}
                                className={cn("cursor-pointer text-start",
                                    heading.level >= 3 && "pl-3",
                                    heading.id === activeId ? "text-accent-soft-foreground" : "text-muted",
                                )}
                            >
                                {heading.text}
                            </Link>
                        ))}
                    </div>
                </nav>
            )}

            {/* content actions (bookmark / share / fullscreen) — moved from the inline bar */}
            <ContentActions />

            {/* "review this lesson" — flashcard decks linked to this content */}
            <LessonFlashcards />

            {/* "practice this lesson" — challenges of this content (closes the loop). Hidden ON
                the Challenges tab, where the body already lists them (avoid the duplicate). */}
            {contentTab !== ContentTab.Challenges && <LessonChallenges />}
        </>
    )

    // mobile bottom-tab "On this page" view: full-width panel, no rail chrome
    if (mobile) {
        return <div className={"flex flex-col gap-6 p-6"}>{body}</div>
    }

    return (
        <aside
            className={cn(
                "hidden w-64 shrink-0 @app-lg:ml-8 @app-lg:block @app-lg:sticky @app-lg:top-16 @app-lg:self-start @app-lg:max-h-[calc(100dvh-4rem)]")}
        >
            {/* ScrollShadow owns the overflow + fades the top/bottom edges so a long
                outline reads as scrollable (the rail often overflows the viewport). */}
            <ScrollShadow hideScrollBar className="@app-lg:max-h-[calc(100dvh-4rem)] @app-lg:overflow-y-auto">
                <div className="flex flex-col gap-6 p-6 pl-0">{body}</div>
            </ScrollShadow>
        </aside>
    )
}

export default OnThisPage

import React from "react"
import { ArrowRightIcon } from "@phosphor-icons/react"
import { ContentRelatedList, type ContentRelatedItem } from "@/components/blocks/learn/ContentRelatedList"
import { SubmissionAttemptSelector, type SubmissionAttempt } from "@/components/blocks/learn/SubmissionAttemptSelector"
import { SubmissionFindingsList, type SubmissionFinding } from "@/components/blocks/learn/SubmissionFindingsList"
import { SubmissionResultHeader } from "@/components/blocks/learn/SubmissionResultHeader"
import { SubmissionScoreCard, type AiModelCategory } from "@/components/blocks/learn/SubmissionScoreCard"
import { Button } from "@/components/atoms/buttons/Button"
import { Typography } from "@/components/atoms/text/Typography"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { Container } from "@/components/frames/Container"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * `PersonalProjectResultScreen` — what came back from grading one capstone task
 * attempt: near-total reuse of `ChallengeResultPage`'s blocks
 * (`SubmissionResultHeader`, `SubmissionAttemptSelector`, `SubmissionScoreCard`,
 * `SubmissionFindingsList`, `ContentRelatedList`), plus an inline capstone
 * "what's next" handoff card. The score cluster is conditional on an attempt being
 * selected (`NoSelection` shows two blocks, not five). The related-reading nudge
 * appears only on a failing attempt; the next-task handoff only on a passing one
 * with a `nextTask` set — the two never overlap.
 */

/** One milestone task waiting once the current one is marked passing. */
export interface PersonalProjectNextTask {
    /** Task title — the only thing the handoff card needs to name it. */
    title: string
}

/** Section eyebrow the handoff card owns itself (§14d.1) — never handed in by the caller. */
const NEXT_TASK_EYEBROW = "Next milestone"
/** CTA label the handoff card owns itself. */
const NEXT_TASK_CTA_LABEL = "Go to the next task"
/**
 * Link text for the capstone's submission link. Overrides `SubmissionScoreCard`'s
 * generic "View submission" default: a capstone submission is always a GitHub repo
 * (unlike a challenge submission, which the sibling screen leaves generic), so this
 * block owns the more specific wording itself (§14d.1) rather than taking a label
 * string from the caller.
 */
const GITHUB_LINK_LABEL = "View on GitHub"

/** Props for the next-task handoff card. Local to this file — see the file header. */
interface MilestoneUpNextCardProps {
    /** The next milestone task to hand the learner off to. */
    task: PersonalProjectNextTask
    /** Fired when the learner presses through to the next task. */
    onGoToNextTask?: () => void
    /** `true` → every composed atom mirrors shimmer instead of the real title. */
    isSkeleton?: boolean
}

/**
 * "You passed — here's what's next." A private composition helper (like
 * `ContinueCard.tsx`'s own `CardBody`), not a node with its own anatomy badge —
 * every part IT renders (`SurfaceCard`/`StackH`/`StackV`/`Typography`/`Button`)
 * badges itself individually, the same way `CardBody` lets its callers' real
 * parts show up in the tree without a synthetic wrapper name in between.
 *
 * @param props - {@link MilestoneUpNextCardProps}
 */
const MilestoneUpNextCard = ({
    task,
    onGoToNextTask,
    isSkeleton = false,
}: MilestoneUpNextCardProps) => {
    const titleColumn = (
        <StackV
            gap={1}
            classNames={["min-w-0"]}

            items={[
                () => (
                    <Typography
                        size="xs"
                        color="muted"
                        isSkeleton={isSkeleton}
                        text={NEXT_TASK_EYEBROW}

                    />
                ),
                () => (
                    <Typography
                        size="base"
                        weight="semibold"
                        truncate
                        isSkeleton={isSkeleton}
                        text={task.title}

                    />
                ),
            ]}
        />
    )

    return (
        <SurfaceCard
            isHighlight
            isSkeleton={isSkeleton}

            body={() => (
                <StackH
                    gap={4}
                    principle="content-row"
                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                    justify="between"
                    align="center"
                    at="sm"

                    items={[
                        () => titleColumn,
                        () => (
                            <Button
                                isSkeleton={isSkeleton}
                                variant="primary"
                                size="sm"
                                label={NEXT_TASK_CTA_LABEL}
                                suffixIcon={ArrowRightIcon}
                                iconSlide
                                onPress={onGoToNextTask}
                                classNames={["w-fit", "shrink-0"]}
                            />
                        ),
                    ]}
                />
            )}
        />
    )
}

/** Props for {@link PersonalProjectResultScreen}. */
export interface PersonalProjectResultScreenProps {
    /** Back-link label, e.g. "Back to task". */
    backLabel: string
    /** Fired when the learner leaves the result page for the task solve page. */
    onBack: () => void
    /** The graded task's title. */
    title: string
    /** The task's own description/prompt. */
    description?: string

    /** The attempts offered in the selector row, in display order. */
    attempts: Array<SubmissionAttempt>
    /** The attempt currently being viewed. Unset → the score section stays hidden. */
    selectedAttemptId?: string
    /** Fired with the id of the attempt the reader picked. */
    onSelectAttempt: (id: string) => void
    /** Accessible name for the attempt selector row. */
    attemptsAriaLabel: string
    /** How many MORE attempts exist beyond the selector row — set (and > 0) → the "+N" trigger shows. */
    overflowCount?: number
    /** Fired when the reader presses "+N" — what it opens is a caller/screen decision (Rule 7). */
    onOverflowPress?: () => void

    /** Section label above the score card, e.g. "Result". */
    scoreLabel: string
    /** Points earned on the selected attempt. Ignored while no attempt is selected. */
    score?: number
    /** Points the selected attempt was scored out of. */
    maxScore?: number
    /** Whether the selected attempt cleared the pass bar — also gates the related-reading nudge and the next-task handoff. */
    isPassing?: boolean
    /** A short line of grader feedback for the selected attempt. */
    shortFeedback?: string
    /**
     * Link to the full submission. A capstone submission is always a GitHub repo
     * (see the `GITHUB_LINK_LABEL` constant above) — named `submissionUrl` to keep
     * one shared vocabulary with the sibling `ChallengeResultPage` prop of the
     * same role, even though its content here is always a GitHub URL.
     */
    submissionUrl?: string
    /** The model that graded the selected attempt. Omit → the byline row drops. */
    gradedByModel?: string
    /** Cost/quality tier of {@link gradedByModel}. */
    modelCategory?: AiModelCategory
    /** Relative time since grading, already localized. */
    timeAgo?: string

    /** Section label above the findings accordion, e.g. "Feedback". */
    findingsLabel: string
    /** The selected attempt's findings, in ANY order — the block re-sorts them. */
    findings: Array<SubmissionFinding>
    /** Repo URL the selected attempt was submitted from — turns each finding's `location` into a deep-link. */
    repositoryUrl?: string

    /** Related lessons, shown only while the selected attempt failed. */
    relatedItems: Array<ContentRelatedItem>
    /** Label for the related-reading section. */
    relatedLabel: string

    /** The next milestone task. Unset → the handoff card never appears, even on a pass. */
    nextTask?: PersonalProjectNextTask
    /** Fired when the learner presses through to the next task. */
    onGoToNextTask?: () => void

    /**
     * `true` → every block that can mirror itself does, and the score/findings
     * cluster reserves its height even though no attempt is selected yet — the
     * same reasoning `ChallengeResultPage` documents for its own cluster.
     */
    isSkeleton?: boolean
}

/**
 * The capstone (personal-project) grading-result screen. See the file header
 * for the full contract, the reuse list, and why the next-task handoff is a
 * new small card rather than a reuse of `ContinueCardHero`.
 *
 * @param props - {@link PersonalProjectResultScreenProps}
 */
const PersonalProjectResultScreen = ({
    backLabel,
    onBack,
    title,
    description,
    attempts,
    selectedAttemptId,
    onSelectAttempt,
    attemptsAriaLabel,
    overflowCount,
    onOverflowPress,
    scoreLabel,
    score,
    maxScore,
    isPassing = false,
    shortFeedback,
    submissionUrl,
    gradedByModel,
    modelCategory,
    timeAgo,
    findingsLabel,
    findings,
    repositoryUrl,
    relatedItems,
    relatedLabel,
    nextTask,
    onGoToNextTask,
    isSkeleton = false,
}: PersonalProjectResultScreenProps) => {
    // Nothing about "how did it go" can render before an attempt is actually
    // selected — see the file header. A skeleton paint still reserves this
    // cluster's height so the page does not jump once the first attempt lands.
    const hasSelection = isSkeleton || selectedAttemptId != null
    // Optional addendum, not the reason the page exists — no isSkeleton override,
    // same treatment ChallengeResultPage gives its related-reading nudge.
    const showNextTaskHandoff = isPassing && nextTask != null

    // Nothing about "how did it go" can render before an attempt is actually
    // selected — see the file header.
    const scoreCluster = hasSelection ? (
        <StackV
            gap={6}

            items={[
                () => (
                    <SubmissionScoreCard

                        label={scoreLabel}
                        score={score ?? 0}
                        maxScore={maxScore}
                        isPassing={isPassing}
                        shortFeedback={shortFeedback}
                        submissionUrl={submissionUrl}
                        submissionLabel={GITHUB_LINK_LABEL}
                        gradedByModel={gradedByModel}
                        modelCategory={modelCategory}
                        timeAgo={timeAgo}
                        isSkeleton={isSkeleton}

                    />
                ),
                () => (
                    <SubmissionFindingsList

                        label={findingsLabel}
                        findings={findings}
                        repositoryUrl={repositoryUrl}
                        isSkeleton={isSkeleton}

                    />
                ),
                // Nothing left to fix on a passing attempt — see file header.
                ...(!isPassing ? [() => (
                    <ContentRelatedList

                        items={relatedItems}
                        label={relatedLabel}
                        isSkeleton={isSkeleton}

                    />
                )] : []),
                // Forward handoff to the next milestone task — only once this one passed.
                ...(showNextTaskHandoff ? [() => (
                    <MilestoneUpNextCard
                        task={nextTask as PersonalProjectNextTask}
                        onGoToNextTask={onGoToNextTask}
                        isSkeleton={isSkeleton}

                    />
                )] : []),
            ]}
        />
    ) : null

    const screenBody = (
        <StackV
            gap={6}

            items={[
                () => (
                    <SubmissionResultHeader

                        backLabel={backLabel}
                        onBack={onBack}
                        title={title}
                        description={description}
                        isSkeleton={isSkeleton}

                    />
                ),
                () => (
                    <SubmissionAttemptSelector

                        attempts={attempts}
                        selectedId={selectedAttemptId}
                        onSelect={onSelectAttempt}
                        ariaLabel={attemptsAriaLabel}
                        overflowCount={overflowCount}
                        onOverflowPress={onOverflowPress}
                        isSkeleton={isSkeleton}

                    />
                ),
                () => scoreCluster,
            ]}
        />
    )

    return <Container size="md" padding={6} body={() => screenBody} />
}

export { PersonalProjectResultScreen }

import React from "react"
import { StatRibbon, type StatRibbonItem } from "@/components/composites/stats/StatRibbon"

/**
 * `PlaygroundDeviceSnapshot` — "Your machine": the paired agent's raw hardware
 * report turned into the same 4-cell `StatRibbon` the Lab route shows, so setup and
 * the live lab agree about what the machine can run. Reuses `StatRibbon`; the block
 * owns the domain judgement — bytes → GB rounding, the `win32`/`darwin`/`linux` →
 * "Windows"/"macOS"/"Linux" table, and the three sentences a GPU cell can say
 * depending on which of `gpu`/`vramTotalMb`/`vramFreeMb` came back. Every
 * `deviceInfo` combination and `isSkeleton` are states of the 4-cell shape.
 */

/**
 * The paired agent's hardware/OS snapshot, exactly as it arrives over the
 * `device:info` socket message — ported faithfully from
 * `PlaygroundDeviceInfo` in
 * `src/components/features/learn/Playground/PlaygroundPrepare/index.tsx`
 * (itself mirroring `PlaygroundByomDeviceInfoSocketIoMessage`).
 */
export interface PlaygroundDeviceInfo {
    /** `win32` | `linux` | `darwin`. */
    platform: string
    /** CPU architecture (`x64`, `arm64`, …). */
    arch: string
    /** Machine hostname. */
    hostname: string
    /** CPU model string. */
    cpuModel: string
    /** Logical CPU core count. */
    cpuCores: number
    /** Total RAM in bytes. */
    totalMemBytes: number
    /** Free RAM in bytes (at snapshot time). */
    freeMemBytes: number
    /** First discrete GPU name, or `null` if it couldn't be read. */
    gpu: string | null
    /** Free GPU VRAM in MiB (NVIDIA only); omitted when no NVIDIA GPU. */
    vramFreeMb?: number
    /** Total GPU VRAM in MiB (NVIDIA only); omitted when no NVIDIA GPU. */
    vramTotalMb?: number
}

/** Bytes → whole GB, the unit the ribbon reads in. */
const gbOf = (bytes: number): number => Math.round(bytes / 1e9)

/**
 * Node's `process.platform` id → the name a learner recognises.
 * @param platform - `win32` / `darwin` / `linux` (or anything else, passed through).
 */
const platformLabel = (platform: string): string =>
    platform === "win32"
        ? "Windows"
        : platform === "darwin"
            ? "macOS"
            : platform === "linux" ? "Linux" : platform

/**
 * The GPU cell's detail line: total + free VRAM when the agent could read an
 * NVIDIA card, an empty second line when a GPU exists but VRAM couldn't be
 * read, or an explicit "unknown" when no GPU was detected at all — three
 * distinct facts, not one string with a blank filled in.
 */
const vramDetail = (gpu: string | null, vramTotalMb?: number, vramFreeMb?: number): string =>
    vramTotalMb
        ? `${Math.round(vramTotalMb / 1024)} GB VRAM${vramFreeMb != null ? ` · ${vramFreeMb} MB free` : ""}`
        : gpu ? "" : "couldn't read"

/**
 * One ribbon cell's label: the fixed category word, plus the computed detail
 * when there is one — `StatRibbonItem.label` is a plain `string` (the ribbon
 * renders it itself through `Typography`), so caption and detail join into a
 * single line instead of the old two-line `<span>`.
 */
const deviceStatLabel = (caption: string, detail: string): string =>
    detail ? `${caption} · ${detail}` : caption

/** Props for {@link PlaygroundDeviceSnapshot}. */
export interface PlaygroundDeviceSnapshotProps {
    /** The paired machine's hardware/OS snapshot to render as a stat ribbon. */
    deviceInfo: PlaygroundDeviceInfo
    /** `true` → every cell's value/detail line swaps to its own shimmer. */
    isSkeleton?: boolean
}

/**
 * "Your machine": the paired agent's hardware report as a 4-cell stat ribbon
 * (OS · CPU · RAM · GPU). See the file header for the unit math, the
 * platform-name table, and why this composes `StatRibbon` instead of a new
 * shape.
 *
 * @param props - {@link PlaygroundDeviceSnapshotProps}
 */
const PlaygroundDeviceSnapshot = ({
    deviceInfo,
    isSkeleton = false,
}: PlaygroundDeviceSnapshotProps) => {
    const items: ReadonlyArray<StatRibbonItem> = [
        {
            key: "os",
            value: platformLabel(deviceInfo.platform),
            label: deviceStatLabel("Operating system", `${deviceInfo.arch} · ${deviceInfo.hostname}`),
        },
        {
            key: "cpu",
            value: `${deviceInfo.cpuCores} cores`,
            label: deviceStatLabel("CPU", deviceInfo.cpuModel),
        },
        {
            key: "ram",
            value: `${gbOf(deviceInfo.totalMemBytes)} GB`,
            label: deviceStatLabel("RAM", `${gbOf(deviceInfo.freeMemBytes)} GB free`),
        },
        {
            key: "gpu",
            value: deviceInfo.gpu ?? "—",
            label: deviceStatLabel("GPU", vramDetail(deviceInfo.gpu, deviceInfo.vramTotalMb, deviceInfo.vramFreeMb)),
        },
    ]

    return (
        <StatRibbon
            valueType="body"
            isSkeleton={isSkeleton}
            items={items}
        />
    )
}

export { PlaygroundDeviceSnapshot }

"use client"

import React, { useCallback } from "react"
import { useLocale, useTranslations } from "next-intl"
import { useParams, useRouter } from "next/navigation"
import { Typography } from "@heroui/react"
import { BackLink } from "@/components/blocks/navigation/BackLink"
import { ProgressMeter } from "@/components/composites/stats/ProgressMeter"
import { Box } from "@/components/frames/Box"
import { usePlaygroundSessionContext } from "@/components/providers/PlaygroundSessionProvider"
import { pathConfig } from "@/resources/path"

/** Props for {@link PlaygroundHeader}. */
export interface PlaygroundHeaderProps {
    /** 1-based step position, rendered as a counter + progress meter. */
    step: {
        current: number
        total: number
    }
}

/**
 * The chrome for the Session work surface: a back-link out to the exercise's
 * Setup page + the step counter/progress.
 *
 * `Exit` returns to Setup (`[slug]`, the exercise overview — device specs +
 * readiness), NOT the hub list — the learner just came from there, and it's
 * the single entry back into this exercise. (Correction 2026-07-20: this
 * header used to also carry a `Prepare · Lab` route switch, but Setup never
 * rendered it — the switch was dead on one leg — so it's gone; Setup is
 * reached only via `Exit`.)
 *
 * @param props - See {@link PlaygroundHeaderProps}.
 */
export const PlaygroundHeader = ({ step }: PlaygroundHeaderProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const { slug } = usePlaygroundSessionContext()
    // Course comes from the URL, NOT the store: playgrounds are shared by every
    // course, and a stale `state.course.displayId` would navigate the learner OUT
    // of the course they're in (bug: every playground link jumped to devops).
    const params = useParams()
    const courseDisplayId = String(params.courseId ?? "")

    const learnPath = pathConfig().locale(locale).course(courseDisplayId).learn()

    const onLeave = useCallback(() => {
        router.push(learnPath.playground(slug).build())
    }, [router, learnPath, slug])

    return (
        <div className="border-b border-default bg-surface px-4 py-3 @app-sm:px-6">
            <div className="flex items-center justify-between gap-3">
                <BackLink label={t("playground.session.leave")} onPress={onLeave} />
                <Typography type="body-sm" weight="medium" color="muted" className="whitespace-nowrap">
                    {t("playground.session.stepCounter", { current: step.current, total: step.total })}
                </Typography>
            </div>
            <Box className="mt-2">
                <ProgressMeter
                    value={step.current}
                    max={Math.max(step.total, 1)}
                />
            </Box>
        </div>
    )
}

"use client"

import React, { useEffect, useRef, useState } from "react"
import { useTranslations } from "next-intl"
import {
    Button,
    Input,
    ScrollShadow,
    Tabs,
    TextArea,
    TextField,
    Typography,
    cn,
} from "@heroui/react"
import {
    CodeIcon,
    FileArrowUpIcon,
    PaperPlaneTiltIcon,
    SparkleIcon,
    StackIcon,
} from "@phosphor-icons/react"
import { ExtendedTabs } from "@/components/blocks/navigation/ExtendedTabs"
import { TabsCard } from "@/components/blocks/navigation/TabsCard"
import { SelectableCardGroup } from "@/components/blocks/navigation/SelectableCardGroup"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { Typography as HouseTypography } from "@/components/atoms/text/Typography"
import { AsyncContentEmpty } from "@/components/composites/async/AsyncContent"
import { MarkdownContent } from "@/components/blocks/rendering/MarkdownContent"
import { RagSourceGraph } from "@/components/blocks/rendering/RagSourceGraph"
import { GithubIcon } from "@/components/svg/GithubIcon"
import { RagPlaygroundSourceKind, RAG_SAMPLES } from "./source"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** One retrieved source chunk backing an answer (mirrors the socket `rag:citations` shape). */
interface PlaygroundRagWorkspaceSource {
    /** File path (or synthetic label) the chunk came from. */
    filePath: string
    /** Truncated excerpt of the chunk's content. */
    snippet: string
    /** Retrieval score (0-1), when the local retriever reports one. */
    score?: number
}

/** One asked-and-(possibly-still-)answering turn in the local Q&A thread. */
interface PlaygroundTurn {
    /** The `runId` correlating this turn to its streamed `rag:answer`/`rag:citations`. */
    id: string
    question: string
    answerText: string
    sources: Array<PlaygroundRagWorkspaceSource>
    done: boolean
    asking: boolean
}

/** Which view a turn's sources section renders — the plain citation list, or a graph of question→source edges. */
type SourcesViewMode = "doc" | "graph"

/** All four import kinds — the agent now resolves sample (built-in catalog) and github (REST) too, not just inline code. */
type WorkspaceImportKind = RagPlaygroundSourceKind

/** Flat chat input — the composer pill owns fill/padding; Input is just where you type. */
const FLAT_CHAT_INPUT_CLASS =
    "w-full !rounded-none border-0 !bg-transparent !p-0 !shadow-none ring-0 focus:ring-0 hover:!bg-transparent focus:!bg-transparent data-[hovered=true]:!bg-transparent data-[focused=true]:!bg-transparent"

/** Props for the {@link PlaygroundRagWorkspace} feature. */
export interface PlaygroundRagWorkspaceProps extends WithClassNames<undefined> {
    /** Latest streamed answer chunk from the agent (`state.ragAnswer`), or `null`. */
    ragAnswer: { runId: string; text: string; done: boolean } | null
    /** Latest citations from the agent (`state.ragCitations`), or `null`. */
    ragCitations: { runId: string; sources: Array<PlaygroundRagWorkspaceSource> } | null
    /** Emit `rag:index` — ask the connected agent to index a source (the parent owns the socket). */
    sendRagIndex: (source: { kind: string; code?: string; fileName?: string; githubUrl?: string; sampleId?: string }) => void
    /** Emit `rag:ask` — ask the connected agent a question over the indexed code, correlated by `runId`. */
    sendRagAsk: (runId: string, question: string) => void
}

/**
 * Machine-backed RAG workspace — the RIGHT pane of a `kind: "rag"`
 * {@link import("@/components/blocks/learn/PlaygroundRagSession").PlaygroundRagSession}.
 * A chat UX (import → ask → streamed answer bubbles → citations with a per-turn
 * "Docs / Diagram" source toggle) that runs over the Playground BYOM socket —
 * the learner's own local Ollama, relayed by the paired CLI agent. This is the
 * app's ONLY RAG surface (the old server-side marketing demo was removed).
 *
 * Purely presentational over the socket: the parent `PlaygroundRagSession` owns
 * the `usePlaygroundByomSocketIo` hook and passes the streamed `ragAnswer` /
 * `ragCitations` down plus the `sendRagIndex` / `sendRagAsk` emitters. This
 * component holds only the local composer + turn-thread state, folding each
 * streamed chunk into the matching turn by `runId`.
 *
 * Import supports all four sources — paste / upload (inline code), a built-in
 * sample from the static {@link RAG_SAMPLES} catalog, or a public GitHub repo:
 * the agent resolves sample id → local catalog code and github URL → repo files
 * (via the GitHub REST API) before chunking + embedding.
 *
 * @param props - See {@link PlaygroundRagWorkspaceProps}.
 *
 * @see Story: .storybook/stories/features/learn/Playground/PlaygroundRagWorkspace/PlaygroundRagWorkspace.stories
 */
export const PlaygroundRagWorkspace = ({
    ragAnswer,
    ragCitations,
    sendRagIndex,
    sendRagAsk,
    className,
}: PlaygroundRagWorkspaceProps) => {
    const t = useTranslations()

    // ── import ────────────────────────────────────────────────────────────
    const [importKind, setImportKind] = useState<WorkspaceImportKind>(RagPlaygroundSourceKind.Paste)
    const [pasteCode, setPasteCode] = useState("")
    const [uploadFileName, setUploadFileName] = useState<string>()
    const [uploadCode, setUploadCode] = useState("")
    const [githubUrl, setGithubUrl] = useState("")
    // built-in catalog is a static id+label list (the agent owns the code and
    // resolves the chosen id locally on index) — pre-select the first so the
    // Sample tab is never empty.
    const [selectedSampleId, setSelectedSampleId] = useState<string>(RAG_SAMPLES[0].id)
    const [imported, setImported] = useState(false)

    // ── chat ──────────────────────────────────────────────────────────────
    const [question, setQuestion] = useState("")
    const [turns, setTurns] = useState<Array<PlaygroundTurn>>([])
    const [sourcesModeByTurn, setSourcesModeByTurn] = useState<Record<string, SourcesViewMode>>({})
    // monotonic fallback id when crypto.randomUUID is unavailable.
    const runCounterRef = useRef(0)

    const canImport = (() => {
        switch (importKind) {
        case RagPlaygroundSourceKind.Paste:
            return pasteCode.trim().length > 0
        case RagPlaygroundSourceKind.Upload:
            return uploadCode.trim().length > 0
        case RagPlaygroundSourceKind.Sample:
            return selectedSampleId != null
        case RagPlaygroundSourceKind.Github:
            return githubUrl.trim().length > 0
        default:
            return false
        }
    })()

    // a turn is still streaming while its last entry isn't done → block a new ask.
    const busy = turns.length > 0 && !turns[turns.length - 1].done

    // fold each streamed answer chunk into the matching turn (by runId).
    useEffect(() => {
        if (!ragAnswer) {
            return
        }
        setTurns((prev) => prev.map((turn) => (
            turn.id === ragAnswer.runId
                ? { ...turn, answerText: ragAnswer.text, done: ragAnswer.done, asking: false }
                : turn
        )))
    }, [ragAnswer])

    // attach citations to the matching turn (by runId).
    useEffect(() => {
        if (!ragCitations) {
            return
        }
        setTurns((prev) => prev.map((turn) => (
            turn.id === ragCitations.runId ? { ...turn, sources: ragCitations.sources } : turn
        )))
    }, [ragCitations])

    const onFileChange = (file?: File) => {
        if (!file) {
            return
        }
        setUploadFileName(file.name)
        const reader = new FileReader()
        reader.onload = () => setUploadCode(String(reader.result ?? ""))
        reader.readAsText(file)
    }

    const onImport = () => {
        if (!canImport) {
            return
        }
        switch (importKind) {
        case RagPlaygroundSourceKind.Paste:
            sendRagIndex({ kind: RagPlaygroundSourceKind.Paste, code: pasteCode })
            break
        case RagPlaygroundSourceKind.Upload:
            sendRagIndex({ kind: RagPlaygroundSourceKind.Upload, code: uploadCode, fileName: uploadFileName })
            break
        case RagPlaygroundSourceKind.Sample:
            sendRagIndex({ kind: RagPlaygroundSourceKind.Sample, sampleId: selectedSampleId })
            break
        case RagPlaygroundSourceKind.Github:
            sendRagIndex({ kind: RagPlaygroundSourceKind.Github, githubUrl: githubUrl.trim() })
            break
        }
        setImported(true)
        setTurns([])
        setSourcesModeByTurn({})
    }

    const onAsk = () => {
        const trimmed = question.trim()
        if (!trimmed || !imported || busy) {
            return
        }
        setQuestion("")
        const runId =
            typeof crypto !== "undefined" && crypto.randomUUID
                ? crypto.randomUUID()
                : `pending-${(runCounterRef.current += 1)}`
        setTurns((prev) => [
            ...prev,
            { id: runId, question: trimmed, answerText: "", sources: [], done: false, asking: true },
        ])
        sendRagAsk(runId, trimmed)
    }

    const IMPORT_TABS = [
        {
            key: RagPlaygroundSourceKind.Paste,
            label: t("ragPlayground.import.tabs.paste"),
            icon: <CodeIcon aria-hidden focusable="false" className="size-4" />,
        },
        {
            key: RagPlaygroundSourceKind.Upload,
            label: t("ragPlayground.import.tabs.upload"),
            icon: <FileArrowUpIcon aria-hidden focusable="false" className="size-4" />,
        },
        {
            key: RagPlaygroundSourceKind.Sample,
            label: t("ragPlayground.import.tabs.sample"),
            icon: <StackIcon aria-hidden focusable="false" className="size-4" />,
        },
        {
            key: RagPlaygroundSourceKind.Github,
            label: t("ragPlayground.import.tabs.github"),
            icon: <GithubIcon aria-hidden className="size-4" />,
        },
    ]

    return (
        <div className={cn("flex h-full flex-col", className)}>
            {/* ── import strip ── */}
            <div className="flex flex-col gap-3 border-b border-default px-4 py-3">
                <TabsCard
                    leftTabs={{
                        items: IMPORT_TABS,
                        selectedKey: importKind,
                        ariaLabel: t("ragPlayground.import.tabsAria"),
                        onSelectionChange: (key) => setImportKind(key as WorkspaceImportKind),
                    }}
                />
                {importKind === RagPlaygroundSourceKind.Paste ? (
                    <TextField aria-label={t("ragPlayground.import.pastePlaceholder")}>
                        <TextArea
                            rows={5}
                            className="font-mono text-sm"
                            placeholder={t("ragPlayground.import.pastePlaceholder")}
                            value={pasteCode}
                            onChange={(event) => setPasteCode(event.target.value)}
                        />
                    </TextField>
                ) : null}
                {importKind === RagPlaygroundSourceKind.Upload ? (
                    <div className="flex flex-col gap-2">
                        <label
                            htmlFor="playground-rag-workspace-upload"
                            className="flex cursor-pointer flex-col items-center justify-center gap-2 rounded-xl border border-dashed border-default bg-surface px-4 py-6 text-center transition-colors hover:bg-default"
                        >
                            <FileArrowUpIcon aria-hidden focusable="false" className="size-6 text-muted" />
                            <Typography type="body-sm" color="muted">
                                {uploadFileName ?? t("ragPlayground.import.uploadHint")}
                            </Typography>
                        </label>
                        <input
                            id="playground-rag-workspace-upload"
                            type="file"
                            accept=".ts,.tsx,.js,.jsx,.py,.go,.java,.cs,.rb,.php,.rs,.cpp,.c,.h,.md,.txt,.json,.yaml,.yml"
                            className="hidden"
                            onChange={(event) => onFileChange(event.target.files?.[0])}
                        />
                    </div>
                ) : null}
                {importKind === RagPlaygroundSourceKind.Sample ? (
                    <div className="flex flex-col gap-2">
                        <Typography type="body-xs" color="muted">
                            {t("ragPlayground.import.sampleHint")}
                        </Typography>
                        <SelectableCardGroup
                            ariaLabel={t("ragPlayground.import.samplePicker.ariaLabel")}
                            items={RAG_SAMPLES.map((sample) => ({
                                value: sample.id,
                                label: sample.label,
                            }))}
                            value={selectedSampleId}
                            onChange={setSelectedSampleId}
                            columns={1}
                        />
                    </div>
                ) : null}
                {importKind === RagPlaygroundSourceKind.Github ? (
                    <div className="flex flex-col gap-2">
                        <Typography type="body-xs" color="muted">
                            {t("ragPlayground.import.githubHint")}
                        </Typography>
                        <TextField aria-label={t("ragPlayground.import.githubPlaceholder")}>
                            <Input
                                placeholder={t("ragPlayground.import.githubPlaceholder")}
                                value={githubUrl}
                                onChange={(event) => setGithubUrl(event.target.value)}
                            />
                        </TextField>
                    </div>
                ) : null}
                <Button
                    variant="primary"
                    size="sm"
                    isDisabled={!canImport}
                    onPress={onImport}
                >
                    {t("ragPlayground.import.cta")}
                </Button>
            </div>

            {/* ── turns thread ── */}
            <ScrollShadow
                hideScrollBar
                className="flex flex-1 flex-col gap-4 overflow-y-auto px-4 py-4"
            >
                {!imported ? (
                    <AsyncContentEmpty
                        icon={CodeIcon}
                        title={t("playground.ragWorkspace.emptyNoImportTitle")}
                    />
                ) : turns.length === 0 ? (
                    <AsyncContentEmpty
                        icon={SparkleIcon}
                        title={t("playground.ragWorkspace.emptyReadyTitle")}
                    />
                ) : (
                    turns.map((turn) => (
                        <div key={turn.id} className="flex flex-col gap-2">
                            <div className="self-end rounded-2xl bg-accent px-4 py-2">
                                <Typography type="body-sm" className="text-accent-foreground">
                                    {turn.question}
                                </Typography>
                            </div>
                            <div className="rounded-2xl border border-default bg-surface px-4 py-3">
                                {turn.answerText ? (
                                    <MarkdownContent markdown={turn.answerText} />
                                ) : !turn.done ? (
                                    <div className="flex items-center gap-2">
                                        <span className="size-2 animate-pulse rounded-full bg-muted" />
                                        <Typography type="body-sm" color="muted">
                                            {t("ragPlayground.chat.thinking")}
                                        </Typography>
                                    </div>
                                ) : null}
                                {turn.sources.length > 0 ? (
                                    <div className="mt-3 flex flex-col gap-2 border-t border-default pt-3">
                                        <div className="flex items-center justify-between gap-2">
                                            <Typography type="body-xs" color="muted">
                                                {t("ragPlayground.chat.sources")}
                                            </Typography>
                                            <ExtendedTabs
                                                size="sm"
                                                selectedKey={sourcesModeByTurn[turn.id] ?? "doc"}
                                                onSelectionChange={(key) => setSourcesModeByTurn((prev) => ({
                                                    ...prev,
                                                    [turn.id]: key as SourcesViewMode,
                                                }))}
                                            >
                                                <Tabs.ListContainer>
                                                    <Tabs.List aria-label={t("ragPlayground.chat.sources")}>
                                                        <Tabs.Tab id="doc">
                                                            {t("ragPlayground.chat.sourcesModeDoc")}
                                                            <Tabs.Indicator />
                                                        </Tabs.Tab>
                                                        <Tabs.Tab id="graph">
                                                            {t("ragPlayground.chat.sourcesModeGraph")}
                                                            <Tabs.Indicator />
                                                        </Tabs.Tab>
                                                    </Tabs.List>
                                                </Tabs.ListContainer>
                                            </ExtendedTabs>
                                        </div>
                                        {(sourcesModeByTurn[turn.id] ?? "doc") === "graph" ? (
                                            <RagSourceGraph question={turn.question} sources={turn.sources} />
                                        ) : (
                                            <SurfaceCardList
                                                variant="nested"
                                                items={turn.sources.map((source, index): SurfaceCardListItem => ({
                                                    key: `${turn.id}-${index}`,
                                                    // monospace is data chrome for source paths — lives inside
                                                    // free-form content (not a SurfaceCard classNames door).
                                                    content: () => (
                                                        <div className="font-mono">
                                                            <HouseTypography size="sm" truncate text={source.filePath} />
                                                            <HouseTypography size="xs" color="muted" truncate text={source.snippet} />
                                                        </div>
                                                    ),
                                                }))}
                                            />
                                        )}
                                    </div>
                                ) : null}
                            </div>
                        </div>
                    ))
                )}
            </ScrollShadow>

            {/* ── composer, pinned at the bottom ── */}
            <div className="border-t border-default px-4 py-3">
                <div className={cn(
                    "flex flex-col gap-2 rounded-2xl bg-default px-3 py-2 focus-within:ring-2 focus-within:ring-accent",
                    !imported && "opacity-60",
                )}
                >
                    <TextField
                        aria-label={t("ragPlayground.chat.placeholder")}
                        className="w-full"
                        isDisabled={!imported}
                    >
                        <Input
                            className={FLAT_CHAT_INPUT_CLASS}
                            placeholder={t("ragPlayground.chat.placeholder")}
                            value={question}
                            onChange={(event) => setQuestion(event.target.value)}
                            onKeyDown={(event) => {
                                if (event.key === "Enter") {
                                    event.preventDefault()
                                    onAsk()
                                }
                            }}
                        />
                    </TextField>
                    <div className="flex w-full items-center justify-end gap-2">
                        <Button
                            isIconOnly
                            size="sm"
                            variant="primary"
                            isDisabled={!imported || busy || !question.trim()}
                            aria-label={t("ragPlayground.chat.send")}
                            onPress={onAsk}
                        >
                            <PaperPlaneTiltIcon aria-hidden focusable="false" className="size-5" />
                        </Button>
                    </div>
                </div>
            </div>
        </div>
    )
}

import React from "react"
import { Typography } from "@/components/atoms/text/Typography"
import { Divider } from "@/components/atoms/display/Divider"
import { StackV, StackH } from "@/components/frames/Stack"

/** Props for the local {@link CommandSkeleton} mirror. */
interface CommandSkeletonProps {
    /** How many placeholder code lines to draw. Defaults to 1. */
    lines?: number
}

/**
 * Placeholder mirror of the code-block chrome `MarkdownContent`'s `pre` renderer
 * draws (border, header divider, lang label) — see file header for why this
 * block owns it instead of `MarkdownContent` shipping an `isSkeleton`.
 */
export const CommandSkeleton = ({ lines = 1 }: CommandSkeletonProps) => (
    <div className="overflow-hidden rounded-2xl border border-default bg-default/30">
        <StackH
            gap={1}
            align="center"
            justify="between"
            padding={{ x: 4, y: 3 }}
            principle="control-pad"
            explain="Control hit-area inset — not row-pad, because this pads a single interactive control rather than a full content row."
            body={() => <Typography size="xs" isSkeleton classNames={["w-1/4"]} />}
        />
        <Divider />
        <StackV
            gap={3}
            padding={4}
            principle="cell-pad"
            explain="Tight cell inset — not card-padding, because this sits inside a dense table or list cell rather than a card body."
            body={() => (
                <StackV
                    gap={3}
                    principle="sibling-stack"
                    explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                    items={Array.from({ length: lines }, (_unused, index) => () => (
                        <Typography size="xs" isSkeleton classNames={[index === lines - 1 ? "w-1/2" : "w-3/4"]} />
                    ))}
                />
            )}
        />
    </div>
)

import React from "react"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { CheckCircleIcon } from "@phosphor-icons/react"
import { MarkdownContent } from "@/components/composites/viewers/MarkdownContent"
import { EmptyState } from "@/components/composites/feedback/EmptyState"
import { Typography } from "@/components/atoms/text/Typography"
import { Button } from "@/components/atoms/buttons/Button"
import { Spinner } from "@/components/atoms/display/Spinner"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * `PlaygroundStepGuide` — the left pane of a playground run: read the current step,
 * run its command on your own machine, ask the agent to verify it. Three shapes:
 *   • `Step` — a step with a command fence; `verifyState` moves through its four
 *     data states inside the one action slot.
 *   • `StepNoCommand` — a read-only explainer step with `commandHint` missing, so the
 *     second `MarkdownContent` node is gone.
 *   • `Complete` — `step` is `undefined`, so the pane is replaced end to end by `EmptyState`.
 */

/** Fenced-code wrapper so the command reuses `MarkdownContent`'s own code-block skin. */
const commandFence = (command: string) => "```bash\n" + command + "\n```"

/** One step's authored content. */
export interface PlaygroundStep {
    /** Step heading, e.g. "Step 2 · Build image". */
    title: string
    /** Instructions body, markdown — what to do and why. */
    body: string
    /** The exact shell command to run. Omitted → a read-only explainer step with no command fence. */
    commandHint?: string
}

/** Where the verify action stands right now. */
export type PlaygroundStepVerifyState =
    | "waitingForConnection"
    | "ready"
    | "pending"
    | "missed"

/** Props for {@link PlaygroundStepGuide}. */
export interface PlaygroundStepGuideProps {
    /** The step being read. `undefined` → every step is done, render the completion leaf. */
    step?: PlaygroundStep
    /** State of the verify action for the current step. Ignored once `step` is `undefined`. */
    verifyState: PlaygroundStepVerifyState
    /** Fired when the learner presses `Verify` (from `ready` or to retry from `missed`). */
    onVerify: () => void
    /** Fired from the completion leaf's back-to-hub action. */
    onLeaveComplete: () => void
    /**
     * `true` → shimmer the step-reading shape, DISTINCT from `step` being
     * `undefined` (which means "run complete", a real business state, not a
     * loading one — see `step`'s own doc).
     */
    isSkeleton?: boolean
}

/**
 * The step-reading pane. See the file header for the leaf/state split and why
 * the pending state draws its own spinner instead of `Button`'s.
 *
 * @param props - {@link PlaygroundStepGuideProps}
 */
const PlaygroundStepGuide = ({
    step,
    verifyState,
    onVerify,
    onLeaveComplete,
    isSkeleton = false,
}: PlaygroundStepGuideProps) => {
    if (isSkeleton) {
        const loadingStep = (
            <>
                <Skeleton className="h-6 w-48 rounded" />
                <StackV
                    gap={2}
                    isSkeleton={isSkeleton}
                    items={[
                        () => <Skeleton className="h-4 w-full rounded" />,
                        () => <Skeleton className="h-4 w-2/3 rounded" />,
                    ]}
                />
                <Skeleton className="h-9 w-36 rounded-xl" />
            </>
        )
        return (
            <div>
                <StackV gap={6} isSkeleton={isSkeleton} items={[() => loadingStep]} />
            </div>
        )
    }
    if (step == null) {
        return (
            <div>
                <EmptyState
                    icon={CheckCircleIcon}
                    tone="neutral"
                    title="All steps completed!"
                    description="You've made it through this playground path. Head back to the hub to pick the next exercise."
                    body={() => (
                        <Button
                            label="Back to Playground hub"
                            variant="secondary"
                            onPress={onLeaveComplete}
                        />
                    )}
                />
            </div>
        )
    }

    // Manual spinner, not `Button`'s own `isPending` skin — see the file header
    // for why an open-ended remote check gets a status row instead of a parked
    // button.
    const verifyPendingStatus = (
        <StackH
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                () => <Spinner size="sm" tone="accent" />,
                () => <Typography size="sm" color="muted" text="Checking…" />,
            ]}
        />
    )

    const verifyControls = (
        <StackV
            gap={2}
            isSkeleton={isSkeleton}
            items={[
                ...(verifyState === "waitingForConnection" ? [() => (
                    <Typography
                        size="sm"
                        color="muted"
                        text="Waiting for a connection to your learning machine…"

                    />
                )] : []),
                ...(verifyState === "ready" || verifyState === "missed" ? [() => (
                    <Button
                        label="Verify this step"
                        variant="primary"
                        onPress={onVerify}

                    />
                )] : []),
                ...(verifyState === "pending" ? [() => verifyPendingStatus] : []),
                ...(verifyState === "missed" ? [() => (
                    <Typography
                        size="xs"
                        color="danger"
                        text="Didn't see the expected result yet — rerun the command and verify again."

                    />
                )] : []),
            ]}
        />
    )

    const commandSection = step.commandHint != null ? (
        <StackV
            gap={2}
            isSkeleton={isSkeleton}
            items={[
                () => <Typography size="xs" weight="medium" color="muted" text="Command to run" />,
                () => (
                    <MarkdownContent
                        source={commandFence(step.commandHint ?? "")}
                        measure="compact"

                    />
                ),
            ]}
        />
    ) : null

    const guideBody = (
        <>
            <Typography size="h4" weight="bold" text={step.title} />
            <MarkdownContent source={step.body} measure="reading" />
            {commandSection}
            {verifyControls}
        </>
    )

    return (
        <div>
            <StackV gap={6} isSkeleton={isSkeleton} items={[() => guideBody]} />
        </div>
    )
}

export { PlaygroundStepGuide }

"use client"

import React, { useState } from "react"
import { Chip, Link, Spinner, cn } from "@heroui/react"
import { CheckCircleIcon, SealCheckIcon } from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import { getTimeAgoLabel, getTimeAgoMessage } from "@/modules/dayjs"
import { ChatBubble } from "@/components/blocks/feed/ChatBubble"
import { MarkdownContent } from "@/components/blocks/rendering/MarkdownContent"
import { ReactionBar } from "@/components/blocks/community/Discussion/ReactionBar"
import { CommentComposer } from "@/components/blocks/community/Discussion/CommentComposer"
import type { ReactionType, CommentNode } from "@/modules/api/graphql/queries/types/discussion"
import type { CommentItemCallbacks } from "@/components/blocks/community/Discussion/CommentItem"
/** Props for {@link QaMessageBubble}. */
export interface QaMessageBubbleProps extends CommentItemCallbacks {
    /** The answer/reply to render. */
    comment: CommentNode
    /** Current viewer id — drives own-bubble alignment + owner edit/delete; null when unknown. */
    currentUserId: string | null
    /** Current viewer identity for the reply composer avatar; null when signed out. */
    currentUser: { username: string, avatar?: string } | null
    /** Loaded reply subtrees, keyed by parent comment id (lazily populated by the container). */
    repliesByParent: Record<string, Array<CommentNode>>
    /**
     * When this bubble is a flattened reply-to-reply, the display name of the author it
     * answers — shown as a small `↳ replying to {name}` tag so threading survives without indent.
     */
    replyToName?: string | null
    /**
     * Whether the viewer may accept this answer — true only for a DIRECT answer when the
     * viewer is the asker. Nested replies are never acceptable, so they leave this off.
     */
    canAccept?: boolean
    /** Accept (or clear) this answer as the accepted one. */
    onAcceptAnswer?: (commentId: string, accepted: boolean) => void
}

/**
 * One answer (or nested reply) in a course-Q&A conversation, rendered as a chat
 * bubble: the viewer's own messages align right on an accent tint, everyone else
 * (peers + founder) aligns left on the surface tint — reusing the canonical
 * {@link ChatBubble}. Identity (name · founder badge · relative time · edited) sits
 * in a header line above the bubble rather than inside it, since {@link ChatBubble}
 * is a plain two-role primitive; the founder is marked in that header, not by
 * recolouring the bubble.
 *
 * Behaviour mirrors the per-lesson {@link import("@/components/blocks/community/Discussion/CommentItem").CommentItem}
 * — 6-emotion {@link ReactionBar}, reply/edit/delete, and lazily-loaded nested replies —
 * so an answer keeps every interaction it had as a forum row. Nested replies are
 * FLATTENED (rendered as sibling bubbles carrying a `↳ replying to {name}` tag) instead of
 * indented, so deep threads never squeeze the bubbles narrower.
 *
 * @param props - {@link QaMessageBubbleProps}
 */
export const QaMessageBubble = ({
    comment,
    currentUserId,
    currentUser,
    repliesByParent,
    replyToName,
    canAccept = false,
    onAcceptAnswer,
    onReply,
    onEdit,
    onDelete,
    onReactComment,
    onLoadReplies}: QaMessageBubbleProps) => {
    const t = useTranslations()
    // transient per-bubble UI state (mirrors CommentItem)
    const [replying, setReplying] = useState(false)
    const [editing, setEditing] = useState(false)
    const [expanded, setExpanded] = useState(false)

    const isMine = currentUserId !== null && currentUserId === comment.author.id
    const isOwner = isMine
    // the container sets the key (even to an empty array) once a load resolves, so
    // its presence — not a local flag — tells us the subtree finished loading
    const repliesLoaded = comment.id in repliesByParent
    const replies = repliesByParent[comment.id] ?? []
    const displayName = isMine ? t("courseQa.you") : comment.author.username

    // expand/collapse the reply subtree, loading it on first expand
    const toggleReplies = () => {
        const next = !expanded
        setExpanded(next)
        if (next && !repliesLoaded) {
            onLoadReplies(comment.id)
        }
    }

    return (
        <div className={cn("flex w-full", isMine ? "justify-end" : "justify-start")}>
            <div className={cn("flex min-w-0 max-w-[92%] flex-col gap-1", isMine && "items-end")}>
                {/* reply-to tag (flattened threading) */}
                {replyToName ? (
                    <span className="rounded-lg bg-accent-soft px-2 py-1 text-xs text-accent-soft-foreground">
                        {t("courseQa.replyingTo", { name: replyToName })}
                    </span>
                ) : null}

                {/* accepted-answer badge — this reply is the chosen answer */}
                {comment.isAcceptedAnswer ? (
                    <Chip size="sm" variant="soft" color="success" className="gap-1">
                        <CheckCircleIcon weight="fill" aria-hidden className="size-3.5 shrink-0" />
                        {t("courseQa.acceptedAnswer")}
                    </Chip>
                ) : null}

                {/* identity header: name (+ founder) + relative time + edited flag */}
                <div className="flex flex-wrap items-center gap-2 px-1 text-xs text-muted">
                    <span className="font-medium text-foreground">{displayName}</span>
                    {comment.isFounderAuthor ? (
                        <span className="inline-flex items-center gap-1 text-accent-soft-foreground">
                            <SealCheckIcon weight="fill" aria-hidden className="size-3.5 shrink-0" />
                            {t("courseQa.founderBadge")}
                        </span>
                    ) : null}
                    <span>{getTimeAgoLabel(getTimeAgoMessage(comment.createdAt), t)}</span>
                    {comment.editedAt ? <span>{t("discussion.edited")}</span> : null}
                </div>

                {/* body: bubble, edit form, or deleted placeholder */}
                {comment.isDeleted ? (
                    <ChatBubble role={isMine ? "user" : "assistant"}>
                        <span className="text-sm italic text-muted">{t("discussion.deletedPlaceholder")}</span>
                    </ChatBubble>
                ) : editing ? (
                    <CommentComposer
                        initialValue={comment.body}
                        submitLabel={t("common.save")}
                        onCancel={() => setEditing(false)}
                        onSubmit={(body) => {
                            onEdit(comment.id, body)
                            setEditing(false)
                        }}
                    />
                ) : (
                    <ChatBubble role={isMine ? "user" : "assistant"}>
                        <MarkdownContent markdown={comment.body} density="compact" flow="embedded" />
                    </ChatBubble>
                )}

                {/* action row: reactions + reply + owner edit/delete */}
                {!comment.isDeleted && !editing ? (
                    <div className={cn("flex flex-wrap items-center gap-3 px-1", isMine && "flex-row-reverse")}>
                        <ReactionBar
                            summary={comment.reactions}
                            onReact={(type: ReactionType | null) => onReactComment(comment.id, type)}
                        />
                        <Link
                            className="cursor-pointer text-xs font-medium text-muted hover:text-foreground"
                            onPress={() => setReplying((prev) => !prev)}
                        >
                            {t("discussion.reply")}
                        </Link>
                        {isOwner ? (
                            <>
                                <Link
                                    className="cursor-pointer text-xs font-medium text-muted hover:text-foreground"
                                    onPress={() => setEditing(true)}
                                >
                                    {t("common.edit")}
                                </Link>
                                <Link
                                    className="cursor-pointer text-xs font-medium text-muted hover:text-danger-soft-foreground"
                                    onPress={() => onDelete(comment.id)}
                                >
                                    {t("common.delete")}
                                </Link>
                            </>
                        ) : null}
                        {/* asker-only: accept this direct answer as THE answer (toggle) */}
                        {canAccept ? (
                            <Link
                                className="cursor-pointer text-xs font-medium text-success-soft-foreground hover:underline underline-offset-4"
                                onPress={() => onAcceptAnswer?.(comment.id, !comment.isAcceptedAnswer)}
                            >
                                {comment.isAcceptedAnswer ? t("courseQa.unaccept") : t("courseQa.accept")}
                            </Link>
                        ) : null}
                    </div>
                ) : null}

                {/* reply composer */}
                {replying ? (
                    <CommentComposer
                        placeholder={t("discussion.replyPlaceholder")}
                        submitLabel={t("discussion.reply")}
                        currentUser={currentUser}
                        onCancel={() => setReplying(false)}
                        onSubmit={(body) => {
                            onReply(comment.id, body)
                            setReplying(false)
                            // surface the new reply immediately by expanding + reloading the subtree
                            setExpanded(true)
                            onLoadReplies(comment.id)
                        }}
                    />
                ) : null}

                {/* replies toggle */}
                {comment.replyCount > 0 ? (
                    <Link
                        className="cursor-pointer self-start px-1 text-xs font-medium text-accent-soft-foreground hover:underline underline-offset-4 decoration-[var(--separator-tertiary)]"
                        onPress={toggleReplies}
                    >
                        {expanded
                            ? t("discussion.hideReplies")
                            : t("discussion.viewReplies", { count: comment.replyCount })}
                    </Link>
                ) : null}

                {/* flattened reply subtree — each reply is a sibling bubble carrying a reply-to tag */}
                {expanded ? (
                    !repliesLoaded ? (
                        <div className="flex w-full justify-center py-1">
                            <Spinner size="sm" />
                        </div>
                    ) : replies.length > 0 ? (
                        <div className="flex w-full flex-col gap-3">
                            {replies.map((reply) => (
                                <QaMessageBubble
                                    key={reply.id}
                                    comment={reply}
                                    currentUserId={currentUserId}
                                    currentUser={currentUser}
                                    repliesByParent={repliesByParent}
                                    replyToName={displayName}
                                    onReply={onReply}
                                    onEdit={onEdit}
                                    onDelete={onDelete}
                                    onReactComment={onReactComment}
                                    onLoadReplies={onLoadReplies}
                                />
                            ))}
                        </div>
                    ) : null
                ) : null}
            </div>
        </div>
    )
}

import React from "react"
import {
    Checkbox as HeroCheckbox,
    CheckboxGroup as HeroCheckboxGroup,
    Radio as HeroRadio,
    RadioGroup as HeroRadioGroup,
} from "@heroui/react"
import { CheckCircleIcon, XCircleIcon } from "@phosphor-icons/react"
import type { AllowedClassName } from "@/components/atoms/_allowed-class-name"
import { Button } from "@/components/atoms/buttons/Button"
import { Typography } from "@/components/atoms/text/Typography"
import { StatusChip } from "@/components/blocks/chips/StatusChip"
import { SectionCard } from "@/components/blocks/cards/SectionCard"
import { StackV } from "@/components/frames/Stack"

/**
 * How many options the learner may pick at once:
 * - `"single"` → radio semantics (exactly one), rendered with HeroUI `RadioGroup`.
 * - `"multiple"` → checkbox semantics (zero or more), rendered with HeroUI `CheckboxGroup`.
 */
export type QuizSelectionMode = "single" | "multiple"

/**
 * One selectable answer of a {@link QuizCard}.
 */
export interface QuizOption {
    /** Stable identity of the option — the value surfaced through `selectedIds` / `onSelectionChange`. */
    id: string
    /** The answer body shown on the row (plain text or a richer `ReactNode`). */
    label: React.ReactNode
    /**
     * Whether this option is a correct answer. Consumed ONLY after `isSubmitted`
     * to paint the per-option success / danger states — ignored before submit so
     * the answer key never leaks early.
     */
    isCorrect?: boolean
}

/**
 * Props for the {@link QuizCard} block.
 *
 * A multiple-choice question card for graded assessments — a question, a list of
 * selectable option rows, an optional check action, and a post-answer explanation.
 * Tier-3 presentational: selection is fully CONTROLLED by the caller
 * (`selectedIds` + `onSelectionChange`) and every callback may be a no-op.
 *
 * Does not take `className` (BLOCK-4) — no live call site forwards one today; a
 * caller that needs a specific placement composes a frame (`StackV`/`StackH`/…)
 * around the card, or passes `classNames` for POSITION only (closed union, same
 * vocabulary `SectionCard`/`MetricCard` already take).
 */
export interface QuizCardProps {
    /**
     * The question prompt (plain text or a richer `ReactNode` — e.g. a code
     * snippet). Rendered prominently above the options.
     */
    question: React.ReactNode
    /**
     * The selectable answers, in display order. Each carries an `id`, a `label`,
     * and an optional `isCorrect` flag used only once `isSubmitted` is `true`.
     */
    options: QuizOption[]
    /**
     * Whether the learner may pick one (`"single"`, radio) or several
     * (`"multiple"`, checkbox) options. Defaults to `"single"`.
     */
    selectionMode?: QuizSelectionMode
    /**
     * The currently selected option ids (CONTROLLED). For `"single"` mode this
     * holds at most one id; for `"multiple"` it holds every picked id.
     */
    selectedIds: string[]
    /**
     * Fired when the selection changes, with the NEXT full list of selected ids.
     * A no-op is valid (e.g. a static, read-only preview).
     */
    onSelectionChange: (ids: string[]) => void
    /**
     * Whether the answer has been submitted. When `true` the options lock
     * (read-only) and each row reveals its correct / incorrect state; the submit
     * action and the pre-answer affordances disappear. Defaults to `false`.
     */
    isSubmitted?: boolean
    /**
     * Fired when the learner presses the submit/check button. Omit it (together
     * with driving `isSubmitted` yourself) to hide the built-in action entirely.
     */
    onSubmit?: () => void
    /**
     * Label for the submit/check button. Defaults to `"Check answer"`. Ignored
     * when `onSubmit` is not provided or once `isSubmitted` is `true`.
     */
    submitLabel?: React.ReactNode
    /**
     * Optional explanation revealed AFTER submit (plain text or a richer
     * `ReactNode`). Shown only while `isSubmitted` is `true`.
     */
    explanation?: React.ReactNode
    /**
     * Optional 1-based position of the question within its quiz. When set, a
     * "Question {n}" chip is shown above the question.
     */
    questionIndex?: number
    /**
     * Where this card sits inside its parent. Appearance is not passable — it
     * is already a prop.
     */
    classNames?: Array<AllowedClassName>
}

/** The mutually-exclusive visual state a single option row can be in. */
type OptionVisualState =
    | "default"
    | "selected"
    | "correct"
    | "incorrect"
    | "correctUnselected"

/**
 * Per-state row classes. Tokens only — correct uses `bg-success-soft` /
 * `text-success-soft-foreground`, incorrect uses the danger-soft pairing, and
 * `correctUnselected` is a subtle success OUTLINE (no soft fill) so a missed
 * correct answer reads as a hint, not an achievement.
 */
const ROW_CLASSES: Record<OptionVisualState, string> = {
    default: "border border-default bg-surface",
    selected: "border border-accent bg-accent-soft text-accent-soft-foreground",
    correct: "border border-success-soft-foreground bg-success-soft text-success-soft-foreground",
    incorrect: "border border-danger-soft-foreground bg-danger-soft text-danger-soft-foreground",
    correctUnselected: "border border-success-soft-foreground bg-surface text-success-soft-foreground",
}

/**
 * Resolves the visual state of one option from the current selection + submit
 * status. Before submit only default / selected are possible (the answer key
 * stays hidden); after submit the success / danger states are revealed.
 */
const resolveOptionState = (
    option: QuizOption,
    isSelected: boolean,
    isSubmitted: boolean,
): OptionVisualState => {
    if (!isSubmitted) {
        return isSelected ? "selected" : "default"
    }
    if (option.isCorrect) {
        return isSelected ? "correct" : "correctUnselected"
    }
    return isSelected ? "incorrect" : "default"
}

/**
 * The trailing result glyph for a post-submit row: a success check on correct
 * answers, a danger cross on a wrongly-picked answer, nothing otherwise.
 */
const OptionResultIcon = ({ state }: { state: OptionVisualState }) => {
    if (state === "correct" || state === "correctUnselected") {
        return (
            <CheckCircleIcon
                aria-hidden
                focusable="false"
                weight="fill"
                className="size-5 shrink-0 text-success-soft-foreground"
            />
        )
    }
    if (state === "incorrect") {
        return (
            <XCircleIcon
                aria-hidden
                focusable="false"
                weight="fill"
                className="size-5 shrink-0 text-danger-soft-foreground"
            />
        )
    }
    return null
}

/** Shared row shell class for every option (spacing + rounded frame + transition). */
const ROW_BASE = "rounded-2xl px-4 py-3 transition-colors"

/** Row shell + its per-state skin. Two static strings — no `cn()` needed to join them. */
const rowClassName = (state: OptionVisualState) => `${ROW_BASE} ${ROW_CLASSES[state]}`

/**
 * QuizCard is a self-framed, multiple-choice question block built on
 * {@link SectionCard}. It stacks an optional "Question {n}" chip, the question, a set
 * of selectable option rows, an optional submit action, and a post-answer
 * explanation. `selectionMode` switches between HeroUI `RadioGroup` (single) and
 * `CheckboxGroup` (multiple) — both with proper group + option ARIA.
 *
 * Before submit, rows show only default / selected (accent) styling so the answer
 * key never leaks. Once `isSubmitted` is `true` the group turns read-only and
 * each row reveals its state: correct → success-soft + check, wrongly-picked →
 * danger-soft + cross, missed-correct → a subtle success outline.
 *
 * Tier-3 presentational: props-only, no store, no SWR, no side-effects; selection
 * is CONTROLLED by the caller and every callback may be a no-op.
 *
 * `missingVocabulary` — the option group stays on raw HeroUI `Radio` /
 * `RadioGroup` / `Checkbox` / `CheckboxGroup` rather than the design system's own
 * `ChoiceRadio` / `ChoiceCheckbox` or `ChoiceRadioGroup`
 * (`composites/form/ChoiceRadioGroup`): neither takes a `ReactNode` option label,
 * neither carries a per-option CORRECTNESS skin (selected / correct / incorrect /
 * correct-but-unselected) with a trailing result glyph, and there is no checkbox
 * equivalent of `ChoiceRadioGroup` at all. Same documented gap
 * `SurfaceCard.SelectableGroup` already carries (`composites/cards/SurfaceCard`:
 * "Calls HeroUI Radio/RadioGroup directly … known drift"). This is a MINIMAL
 * local wrapper for that gap, not a new shared component — the leaves themselves
 * are untouched. Likewise the post-submit explanation panel stays a local
 * `rounded-2xl bg-surface-secondary` surface: no atom/composite renders a
 * neutral panel without alert semantics (`blocks/feedback/Callout` forces a
 * status tint + a required title).
 *
 * @param props - {@link QuizCardProps}
 *
 * @example
 * <QuizCard>
 *   questionIndex={1}
 *   question="Which HTTP status reports a resource that doesn't exist?"
 *   options={[
 *     { id: "a", label: "200 OK" },
 *     { id: "b", label: "404 Not Found", isCorrect: true },
 *   ]}
 *   selectedIds={selectedIds}
 *   onSelectionChange={setSelectedIds}
 *   onSubmit={handleSubmit}
 * />
 * @see Story: .storybook/stories/blocks/learn/QuizCard/QuizCard.stories
 */
export const QuizCard = ({
    question,
    options,
    selectionMode = "single",
    selectedIds,
    onSelectionChange,
    isSubmitted = false,
    onSubmit,
    submitLabel = "Check answer",
    explanation,
    questionIndex,
    classNames,
}: QuizCardProps) => {
    // Option rows — RadioGroup (single) or CheckboxGroup (multiple). Locked
    // read-only after submit so the revealed state can't be edited while staying
    // visually un-dimmed (unlike isDisabled). See the file header's
    // `missingVocabulary` note for why this stays on raw HeroUI components.
    const optionsGroup = selectionMode === "single" ? (
        <HeroRadioGroup
            aria-label="Answer options"
            value={selectedIds[0] ?? ""}
            onChange={(value) => onSelectionChange(value ? [value] : [])}
            isReadOnly={isSubmitted}
            className="flex flex-col gap-2"
        >
            {options.map((option) => {
                const isSelected = selectedIds.includes(option.id)
                const state = resolveOptionState(option, isSelected, isSubmitted)
                return (
                    <HeroRadio key={option.id} value={option.id} className={rowClassName(state)}>
                        <HeroRadio.Content className="w-full">
                            <HeroRadio.Control>
                                <HeroRadio.Indicator />
                            </HeroRadio.Control>
                            <span className="min-w-0 flex-1">{option.label}</span>
                            <OptionResultIcon state={state} />
                        </HeroRadio.Content>
                    </HeroRadio>
                )
            })}
        </HeroRadioGroup>
    ) : (
        <HeroCheckboxGroup
            aria-label="Answer options"
            value={selectedIds}
            onChange={onSelectionChange}
            isReadOnly={isSubmitted}
            className="flex flex-col gap-2"
        >
            {options.map((option) => {
                const isSelected = selectedIds.includes(option.id)
                const state = resolveOptionState(option, isSelected, isSubmitted)
                return (
                    <HeroCheckbox key={option.id} value={option.id} className={rowClassName(state)}>
                        <HeroCheckbox.Content className="w-full">
                            <HeroCheckbox.Control>
                                <HeroCheckbox.Indicator />
                            </HeroCheckbox.Control>
                            <span className="min-w-0 flex-1">{option.label}</span>
                            <OptionResultIcon state={state} />
                        </HeroCheckbox.Content>
                    </HeroCheckbox>
                )
            })}
        </HeroCheckboxGroup>
    )

    return (
        <SectionCard
            identity={{ tier: "block", component: "QuizCard" }}
            classNames={classNames}
        >
            <StackV
                gap={5}
                items={[
                    // Question header: optional index chip + the prompt
                    () => (
                        <StackV
                            gap={3}
                            items={[
                                ...(typeof questionIndex === "number"
                                    ? [() => <StatusChip tone="accent">{`Question ${questionIndex}`}</StatusChip>]
                                    : []),
                                () => <Typography size="base" weight="semibold" text={question} />,
                            ]}
                        />
                    ),
                    () => optionsGroup,
                    // Submit action — hidden once the answer is in or when no handler
                    ...(onSubmit && !isSubmitted
                        ? [() => (
                            <Button
                                label={submitLabel}
                                variant="primary"
                                size="sm"
                                onPress={onSubmit}
                                isDisabled={selectedIds.length === 0}
                                classNames={["w-fit"]}
                            />
                        )]
                        : []),
                    // Explanation — revealed only after submit
                    ...(isSubmitted && explanation
                        ? [() => (
                            <div className="rounded-2xl bg-surface-secondary">
                                <StackV
                                    gap={1}
                                    padding={{ x: 5, y: 4 }}
                                    principle="row-pad"
                                    explain="Row content inset — not cell-pad, because this pads a horizontal content row rather than a dense table cell."
                                    body={() => (
                                        <StackV
                                            gap={2}
                                            principle="title-subtitle"
                                            explain="Title over supporting line — not label-field, because neither line is a form control label."
                                            items={[
                                                () => <Typography size="sm" weight="semibold" text="Explanation" />,
                                                () => <Typography size="sm" color="muted" text={explanation} />,
                                            ]}
                                        />
                                    )}
                                />
                            </div>
                        )]
                        : []),
                ]}
            />
        </SectionCard>
    )
}

