    if (!lessonVideos.length) {
        return <Empty />
    }

    return (
        <StackV
            identity={{ tier: "block", component: "LessonBody" }}
            gap={6}
            items={[
                () => <SearchBar />,
                () => (
                    <StackV gap={4} items={lessonVideos.map((lessonVideo) => () => (
                        <LessonCard key={lessonVideo.id} lessonVideo={lessonVideo} />
                    ))} />
                ),
            ]}
        />
    )
}

