import React, { useMemo } from "react"
import { useTranslations } from "next-intl"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { MarkdownContent } from "@/components/blocks/rendering/MarkdownContent"
import type { MilestoneTaskBrief } from "@/modules/types/entities/milestone"
import { usePersonalProjectGithubForm } from "@/hooks/zustand/personalProjectGithub/usePersonalProjectGithubForm"
import { useAppSelector } from "@/redux/hooks"

/** Props for {@link TaskBrief}. */
export type TaskBriefProps = Record<string, never>

/**
 * Pick the brief matching the selected language, falling back to the first brief (handles the
 * single `agnostic` brief used by FE/infra tasks).
 */
const pickBriefByLang = (
    briefs: Array<MilestoneTaskBrief>,
    lang: string,
): MilestoneTaskBrief | undefined =>
    briefs.find((brief) => brief.lang === lang) ?? briefs[0]

/**
 * The brief `body` is already resolved to the active locale by the backend resolver (one localized
 * body per language, no per-locale translation variants), so we read it directly.
 */
const resolveBriefBody = (
    brief: MilestoneTaskBrief | undefined,
): string => brief?.body ?? ""

/**
 * SCHEMA V2 learner-facing task brief. Renders the per-language Markdown instructions (with
 * `:::muted` callouts, fenced code and ```layout``` widgets) for the selected language, resolved to
 * the active locale. Renders nothing when there are no briefs (legacy tasks).
 *
 * Self-contained: reads `briefs` from redux task state and `lang` from the github form store.
 */
export const TaskBrief = () => {
    const t = useTranslations()
    const { lang } = usePersonalProjectGithubForm()

    const selectedTaskDetail = useAppSelector((state) => state.milestone.selectedTaskDetail)
    const selectedTaskId = useAppSelector((state) => state.milestone.selectedTaskId)
    const milestoneEntities = useAppSelector((state) => state.milestone.entities)

    const displayTask = useMemo(() => {
        if (!selectedTaskId) return undefined
        if (selectedTaskDetail?.id === selectedTaskId) {
            return selectedTaskDetail
        }
        for (const milestone of milestoneEntities) {
            const found = milestone.tasks?.find((task) => task.id === selectedTaskId)
            if (found) return found
        }
        return undefined
    }, [selectedTaskId, selectedTaskDetail, milestoneEntities])

    const briefs = displayTask?.briefs ?? []

    const body = useMemo(
        () => resolveBriefBody(pickBriefByLang(briefs, lang)),
        [briefs, lang],
    )

    if (briefs.length === 0) {
        return null
    }

    return (
        // B37 Decision E/F: generic framed brief → SurfaceCard Base owns label + face.
        <SurfaceCard
            label={t("task.briefTitle")}
            body={() => (
                <div data-ai-selectable>
                    <MarkdownContent markdown={body} />
                </div>
            )}
        />
    )
}

"use client"

import React, {
    useCallback,
    useMemo,
} from "react"
import { Alert, Button } from "@heroui/react"
import {
    useTranslations,
    useLocale,
} from "next-intl"
import {
    useRouter,
} from "next/navigation"
import {
    pathConfig,
} from "@/resources/path"
import { useAppDispatch, useAppSelector } from "@/redux/hooks"
import { setSelectedTaskId } from "@/redux/slices/milestone"
import { useQueryMilestoneTaskProgressSwr } from "@/hooks/swr/api/graphql/queries/useQueryMilestoneTaskProgressSwr"
import { buildMilestoneTaskProgressLookup, isPersonalProjectTaskActionUnlocked } from "@/components/utils/task-lookup"

/** Props for {@link TaskLockedAlert}. */
export type TaskLockedAlertProps = Record<string, never>
/**
 * Warning alert shown when previewing a locked (not-yet-unlocked) task.
 *
 * Self-contained section (single-use): reads the selected/current task ids from
 * redux and the milestone task progress from its singleton SWR query, derives
 * whether the previewed task is locked, and owns the "go to current task"
 * navigation handler. Renders nothing when the action is unlocked, so the task
 * container just drops `<TaskLockedAlert />` in place. `"use client"` for redux,
 * routing and i18n.
 * @param props - optional className (unused; alert shape is fixed)
 */
export const TaskLockedAlert = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const dispatch = useAppDispatch()
    const progressSwr = useQueryMilestoneTaskProgressSwr()
    const selectedTaskId = useAppSelector((state) => state.milestone.selectedTaskId)
    const courseDisplayId = useAppSelector((state) => state.course.displayId)

    const progressLookup = useMemo(
        () => buildMilestoneTaskProgressLookup(
            progressSwr.data?.milestoneTaskProgress?.data?.completionTasks,
        ),
        [progressSwr.data],
    )
    const currentTaskId = progressSwr.data?.milestoneTaskProgress?.data?.currentTask?.id

    const isActionUnlocked = useMemo(
        () => {
            if (!selectedTaskId) {
                return true
            }
            if (progressSwr.isLoading) {
                return true
            }
            return isPersonalProjectTaskActionUnlocked(
                selectedTaskId,
                progressLookup,
                currentTaskId,
            )
        },
        [
            selectedTaskId,
            progressLookup,
            currentTaskId,
            progressSwr.isLoading,
        ],
    )

    const isActionLocked = Boolean(selectedTaskId) && !isActionUnlocked
    const canGoToCurrentTask = Boolean(
        currentTaskId
        && selectedTaskId
        && currentTaskId !== selectedTaskId,
    )

    /** Navigate to the current (unlocked) task from the locked-preview alert. */
    const onGoToCurrentTask = useCallback(
        () => {
            if (!currentTaskId || !courseDisplayId) {
                return
            }
            dispatch(setSelectedTaskId(currentTaskId))
            router.push(
                pathConfig().locale(locale).course(courseDisplayId).learn().personalProject(currentTaskId).build(),
            )
        },
        [
            currentTaskId,
            courseDisplayId,
            dispatch,
            router,
            locale,
        ],
    )

    if (!isActionLocked) {
        return null
    }

    return (
        <>
            <Alert status="warning" className={"shadow-none bg-warning-soft"}>
                <Alert.Indicator />
                <Alert.Content className="gap-2">
                    <Alert.Title>{t("task.previewLockedAlertTitle")}</Alert.Title>
                    <Alert.Description>
                        {t("task.previewLockedAlertDescription")}
                    </Alert.Description>
                    {canGoToCurrentTask ? (
                        <Button
                            size="sm"
                            variant="secondary"
                            className="w-fit shrink-0 bg-background text-warning-soft-foreground"
                            onPress={onGoToCurrentTask}
                        >
                            {t("task.previewLockedGoToCurrentTaskButton")}
                        </Button>
                    ) : null}
                </Alert.Content>
            </Alert>
        </>
    )
}

